$('#compare-run').onclick=()=>{if(!savedA){tell('请先保存方案 A。');return;}try{const mode=$('#compare-source').value,comparison=comparePlans(savedA,config,{mode,...(mode==='guild'?{guild:readCycleGuild(localStorage)}:{})});pair=comparison.reports;pairOrigins=comparison.origins;const metrics=r=>[r.rooms.filter(x=>x.won).length,r.party.filter(u=>u.hp>0).length,r.party.reduce((s,u)=>s+u.hp,0),r.party.reduce((s,u)=>s+u.mp,0),Object.values(r.stats).filter(s=>!s.owner||HEROES.some(h=>h.id===s.owner)).reduce((s,u)=>s+u.defenseMana,0),Object.values(r.stats).filter(s=>!s.owner||HEROES.some(h=>h.id===s.owner)).reduce((s,u)=>s+u.healing,0),Object.values(r.stats).filter(s=>!s.owner||HEROES.some(h=>h.id===s.owner)).reduce((s,u)=>s+u.interrupts,0),Object.values(r.stats).filter(s=>!s.owner||HEROES.some(h=>h.id===s.owner)).reduce((s,u)=>s+u.failed,0),r.events.find(e=>e.type==='effect'&&e.detail.scope==='rounds'&&e.text.includes('潮纹屏障'))?.detail.value??'未施放',r.supplies.herb,r.supplies.rune,r.supplies.arrow,r.config.expedition==='harbor'?r.rooms.map(x=>x.name).join(' → '):(BELL_ROUTES[r.events.find(e=>e.type==='route')?.detail.route]?.name||'无分支记录')];const ma=metrics(pair[0]),mb=metrics(pair[1]);$('#comparison').innerHTML=comparisonBasisView(comparison.basis)+`<h3>共同种子 ${config.seed}</h3><table><thead><tr><th>观察项</th><th>方案 A</th><th>当前 B</th></tr></thead><tbody>${['通过房间','存活队员','剩余生命','剩余法力','防御消耗法力','有效治疗','治疗中断次数','空过行动','首次屏障强度','剩余药草','剩余符纸','剩余箭矢','实际末房路线'].map((k,i)=>`<tr><td>${k}</td><td>${ma[i]}</td><td>${mb[i]}</td></tr>`).join('')}</tbody></table><button data-open-pair="0">打开 A 战报</button> <button data-open-pair="1">打开 B 战报</button><p class="muted">同种子便于复现，不保证修改行动后各检定仍使用同一随机数。单次胜负不能证明方案普遍更强。</p>`;$('#comparison').insertAdjacentHTML('beforeend',comparisonDetails(pair));tell('对比完成。');}catch(e){pair=null;pairOrigins=[];$('#comparison').innerHTML='<p>'+esc(e.message)+'</p>';tell(e.message);}};
$('#comparison').onclick=e=>{const b=e.target.closest('[data-open-pair]');if(b&&pair){const i=Number(b.dataset.openPair);loadReport(pair[i],pairOrigins[i]);}};
$('#rules').onclick=()=>{$('#modal-body').innerHTML=`<p class="eyebrow">规则边界 / 0.57</p><h2>用明确规则验证协作</h2><p>本版是自主实现的 WoD 灵感原型。第三方 wod_local 提供结构参考，没有复制其代码，也不宣称所有公式符合原版。</p><h3>当前结算顺序</h3><p>回合开始 / 延迟效果激活 → 回合前行动 → 法力回复 → 先攻与行动队列 → 道具检查 / 治疗检查 / 普通行动 → 效果到期。</p><h3>属性与修正</h3><p>检定均值：主属性 ×2 + 副属性 + 技能等级 ×2。基础伤害：主属性 ÷2 + 副属性 ÷3 + 技能等级 ÷2。装备和临时属性效果先作用于属性；战技传授作用于攻击技能等级。</p><h3>明确采用原创规则的部分</h3><p>投点使用两个均匀随机值形成三角分布；先攻衰减为 1 / (1 + 0.6 × 已排行动数)。重击 / 致命倍率为 1.25 / 1.5，固定护甲扣除后，再乘以（1−类型抗性/100）并向下取整。负抗性表示弱点；闪避不造成伤害。抗性按近战、远程、法术区分，当前仅封库敌人有非零抗性，不是WoD原版伤害分类。伤势阈值由玩家选择；这些都不是经原版验证的公式。</p><h3>防御与多阶段效果</h3><p>防御检定遵循对应主属性×2+副属性+技能等级×2。自然防御技能等级为0；近战使用灵巧/敏捷、远程使用敏捷/感知、法术使用意志/智力。防御技能费用、基础等级6级和专修+3级是原创规则，缺少装备或法力时回退自然防御。延迟从生效时开始计算持续时间；同名效果有任一组件尚在等待或生效时不会重复施加。</p><h3>目标与效果</h3><p>近战按站位路线选择；远程和法术优先指定位置，无人时转移。群攻不会跨位置补齐。同名增益在目标身上互斥。持续 N 回合指当前与之后 N 回合。房间效果进场前结束，药膳持续整次远征。</p><h3>指令节奏</h3><p>普通指令的每回合一次按指令条目计数，成功施放含闪避后本回合不重试；未满足装备、资源或目标条件不计次数。带有该模式的普通阶段在本人本回合首次检查普通指令时从第一条开始，额外行动沿游标继续后备，下回合重新检查；仍受道具和救护优先级限制。仅配置一条且已经执行时，后续机会可能空过，请保留低耗后备。</p><h3>独立后期职业进阶</h3><p>本项目在累计300经验且公会通关资深试炼后，为六职业分别开放两个独立研修方向；选择支付80经验，当前退回返还80。进阶不删除、锁定或排斥普通技能。实验草稿可试配，公会实际出征采用个人已选择进阶。门槛和数值是项目参数，不宣称原版21级或现行服务器规则。</p><h3>缓释药敷</h3><p>药师可在预备阶段消耗4法力、1药草，覆盖同阵位最多3人；下一及再下一回合开始基础各恢复8生命。同名效果等待或生效时不叠加，不复活，不占普通行动；回合开始先激活延迟效果、再缓释恢复，然后执行预备。它不受只限制自动草药救护的禁疗影响。固定恢复量不因技能等级增长，不能取代当回合救急。</p><h3>守卫援护</h3><p>援护架势预备5法力，为一个阵位最多3名其他友方提供当前/下一回合援护。每位守卫每回合最多付2法力尝试一次近战/远程接招：以体质/感知/援护技能检定，实掷不低于攻击实掷×0.8向上取整才重定向，之后仍正常防御承伤。失败也付费；法力不足不尝试，法术/心理不触发，每次攻击最多重定向一次，不取消群攻其他目标。不是无敌，也不换算避免伤害。</p><h3>多形态召唤与召回</h3><p>潮卫较耐打，使用近战路线；弩灵生命较低，远程优先后排、后排空缺回退，不耗箭矢。普通召唤技能每位主人在所有形态间最多一只存活召唤物；原碎印机关属于场景例外，仍可入场两只潮卫。主人倒下或房间结束消散。潮灵归还在预备阶段付2法力，仅召回自己的召唤物，不退原法力/符纸；无目标免费跳过，召回和重召分别占预备行动。</p><h3>心理攻击</h3><p>诘心回声为6法力单体心理攻击，沿用法术栏的心智抵抗/自然防御，按心理抗性减伤，物理护甲不参与。心理与法术抗性独立，不附挫志；净化不能撤销已经造成的伤害。</p><h3>施法媒介</h3><p>使用符纸的攻击、辅助和召唤指令可分别选择媒介。标准消耗原法力和1符纸；心诵不耗符纸，额外4法力；复写消耗2符纸，法力减少3，最低1。先计算个人后期研修，再应用媒介。它们保持效果、检定、装备和目标规则，不增加行动；缺少本条实际费用时免费跳过，按原游标尝试后备。港口预留按真实支付数量检查。切换到不用符纸的技能会恢复标准媒介。以上均为本原型参数。</p><h3>挫志与净化</h3><p>挫志弦是吟游者需乐器的5法力低伤害单体法术；命中未倒下者附攻击技能等级-3，当前与下一回合有效，不叠加或刷新。影响后续攻击的命中和伤害，不影响防御、辅助或救护；杀死来源不撤销。学者清心符在预备用4法力和1符纸净化同阵位最多3名存活者的负面效果，占用本次预备；无负面目标免费跳过。它保留增益、不复活、不提供免疫、不撤销之前的结果。持续净化后备可用轮转屏障，让下次预备重新检查净化。</p><h3>截疗与先后手</h3><p>学者可选截疗符：6法力、1符纸、需法器，低伤害单体法术。命中仍存活且有救护技能的目标后，仅限制其本回合余下的自动草药救护，回合结束解除；闪避不附着，伤害吸收不阻止附着。同回合不叠加或延长，重复攻击仍付费。目标仍能执行普通指令、使用随身道具；已完成的治疗不撤销。附着次数不等于阻止救护次数，先攻与时机决定是否来得及。该效果敌我一致，默认队伍不启用。</p><h3>训练与装备条件</h3><p>每项永久训练最多额外+3级，逐级消耗20/40/60经验，没有全角色6点硬上限。公会经验不足时不能培养，实验草稿不扣经验。训练跨房间共用，原有专修保留。八项属性也可分别用经验培养，每级+1，沿用20/40/60经验与每项+3上限；生命/法力按既有体质/智力/意志公式在出发时计算，属性与技能不能混称等级。专修+3是本原型的战前加成，不是精通门槛或职业进阶，也不排斥其他普通技能。技能等级进入命中、伤害、辅助或召唤公式；固定数值辅助不会因训练自动增强。自然防御不吃训练等级。盾缘重击需要盾甲类装备，破甲重箭需要弓具类装备，凝潮长枪需要法器类装备；缺少装备时不扣费并尝试下一条指令。破甲只在本次命中计算时忽略部分护甲，不修改目标装备。</p><h3>断潮封库</h3><p>独立挑战：战前最多24份共享物资，每房5回合，拾取药草占第二房间1回合，该房剩4回合。截止时未清场即失败；原有路线与敌人不变。</p><h3>回廊救援</h3><p>封库第二房间进场先救援、后沉钟：赶路无收益；拾取固定获得2药草；救治消耗3药草，存活药师治疗检定难度70，成功获得4符纸和4箭矢，失败仍耗药草。救援使用独立随机流，无额外法力和行动费用，不复活角色、不计战斗治疗。普通路线战前60份、断潮挑战24份、守灯归途36份是携带预算，途中获取可超过该预算。</p><h3>非战斗机关</h3><p>封库试炼第2房间进场、回合前之前自动执行战前选定的机关策略。按当前存活、装备和技能均值择优；不支付该战斗技能本身的法力费用，只支付事件标明的补给。独立种子检定，不消耗战斗随机数序列。未满足条件或补给不足则绕过、不付费。成功增益只给予当前存活正式队员，房间结束清除；失败扣执行者最多12法力。插画不决定结果。解读成功会令末房全体敌人法术抗性降低20个百分点；破拆成功绕过后排护印师，但三名守印者力量+4。路线效果在抵达末房时生效，无额外收费与检定，战报可追溯来源。</p><h3>当前范围</h3><p>五个战斗位置、六人出战与两名可招募候补，多条路线及六场连续章节。已实现独立防御、延迟多组件效果和按房间覆盖。已加入召唤物、每件道具独立次数及潮汐异变挑战；已实现个人成长、固定属性装备掉落和武器／防具／饰品三部位配装；自由探索分支尚未实现。召唤物本房间有效，主人倒下时消散；正式队员全灭即失败。随身道具占用普通行动并保持指令游标，次数跨房间保留。立绘样片使用 AI 生成，弹道和反馈由结算事件驱动；碎印阶段使用预生成CG，仅在对应事件触发时显示；未接入在线CG生成。v0.9新增镜潮回廊场景、固定阵位展示和跨房间连续回放；阵位布局是逻辑位置的可视化，不代表距离、移动或碰撞规则。演出只读取原始战报，不再投骰或改写结果。</p><p><a href="https://github.com/dust1/wod_local" target="_blank" rel="noreferrer">第三方参考项目 ↗</a></p>`;$('#modal').showModal();};$('#close').onclick=()=>$('#modal').close();
planner();persist();

function loadCase(kind){undoConfig=configurationUndo(config);savedA=defaults();config=defaults();scope='';if(kind==='bell'){savedA=archiveConfig();config=clone(savedA);config.bellApproach='study';}if(kind==='archive'){savedA=archiveConfig();config=archiveConfig(true);}if(kind==='training'){savedA=trainingBuild('support');config=trainingBuild('defense');}if(kind==='pierce'){savedA=trainingBuild();config=clone(savedA);config.heroes.find(h=>h.id==='b').main[0]=row('pierce','rear');}if(kind==='shortage'){savedA=challengeConfig();savedA.supplies.arrow=0;savedA.heroes.find(h=>h.id==='b').main=[row('volley','rear')];config=clone(savedA);config.heroes.find(h=>h.id==='b').main.push(row('shot','rear'));}if(kind==='summon'){savedA=challengeConfig();config=clone(savedA);savedA.heroes.find(h=>h.id==='c').prep=[];}if(kind==='item'){savedA=challengeConfig();config=clone(savedA);for(const h of savedA.heroes)h.item='none';}if(kind==='defense'){for(const h of savedA.heroes)h.defenses={melee:'natural',ranged:'natural',magic:'natural'};for(const h of config.heroes)h.defenses={melee:h.id==='a'?'parry':'sidestep',ranged:'dodge',magic:'resist'};}
 if(kind==='delay'){config.heroes.find(h=>h.id==='e').prep=[row('cadence','rear')];savedA.heroes.find(h=>h.id==='e').prep=[row('rhythm','rear')];}
 if(kind==='room'){for(const c of [config,savedA]){c.heroes.forEach(h=>h.defenses.magic='natural');c.heroes.find(h=>h.id==='d').prep=[row('ward','rear')];}config.heroes.find(h=>h.id==='d').overrides.cistern={prep:[row('ward','center')]};scope='cistern';}
 persist();try{localStorage.setItem(storageKey+'-a',JSON.stringify(savedA));}catch{}planner();$('#compare-run').click();tell('示例已载入：A 与 B 只改变所选机制。打开战报查看防御消耗、效果生效或房间覆盖。');}
$('#case-defense').onclick=()=>loadCase('defense');$('#case-delay').onclick=()=>loadCase('delay');$('#case-room').onclick=()=>loadCase('room');

$('#case-summon').onclick=()=>loadCase('summon');$('#case-item').onclick=()=>loadCase('item');

function replaceConfig(next,undo=null){validate(next);undoConfig=undo||configurationUndo(config);config=clone(next);}
function renderPlans(){refreshPlanBook();const select=$('#saved-plans'),chosen=select.value;select.innerHTML='<option value="">选择已保存方案</option>'+plans.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${EXPEDITIONS[p.config.expedition].name}</option>`).join('');if(plans.some(p=>p.id===chosen))select.value=chosen;$('#undo-load').disabled=!undoConfig;$('#undo-load').textContent=undoConfig?.roles?'撤销配置与伙伴职责':'撤销上次载入';$('#undo-description').textContent=undoConfig?.roles?'将恢复载入前配置及'+undoConfig.roles.changes.map(c=>HEROES.find(h=>h.id===c.id).name).join('、')+'的原伙伴职责；期间的训练、装备和其他伙伴调整保留。':'撤销仅保留本次页面会话中最近一次载入前的配置。';$('#plan-count').textContent=plans.length+' / 12 个本机方案';const assigned=plans.find(p=>p.id===planBook.bindings[config.expedition]);$('#plan-binding-state').textContent=planBookError||('当前路线：'+EXPEDITIONS[config.expedition].name+'；'+(assigned?'已分配「'+assigned.name+'」':'未分配，准备入口使用路线初始方案')+'。绑定只影响下次从地图/营地准备；直接切换路线仍保留草稿。');for(const id of ['save-plan','update-plan','bind-plan','unbind-plan','delete-plan','load-plan'])$('#'+id).disabled=Boolean(planBookError)||(['update-plan','bind-plan','delete-plan','load-plan'].includes(id)&&!select.value)||(id==='unbind-plan'&&!assigned);}
function writePlanBook(next){planBookRaw=commitPlanBook(localStorage,planBookRaw,next);planBook=next;plans=next.plans;renderPlans();}
function saveNamed(replace){try{if(planBookError)throw Error(planBookError);const id=replace?$('#saved-plans').value:'plan-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2),next=saveBookPlan(planBook,{id,name:$('#plan-name').value,config},replace);writePlanBook(next);$('#saved-plans').value=id;renderPlans();tell(replace?'所选方案已更新，已有同路线绑定保留。':'新方案已保存，包含完整房间覆盖与补给。');}catch(e){tell('保存失败：'+e.message);}}
$('#save-plan').onclick=()=>saveNamed(false);$('#update-plan').onclick=()=>saveNamed(true);
$('#saved-plans').onchange=()=>{refreshPlanBook();const p=plans.find(p=>p.id===$('#saved-plans').value);if(p)$('#plan-name').value=p.name;renderPlans();};
$('#bind-plan').onclick=()=>{try{writePlanBook(bindBookPlan(planBook,config.expedition,$('#saved-plans').value));tell('本路线方案已分配，当前草稿与公会资产未改变。');}catch(e){tell('分配失败：'+e.message);}};
$('#unbind-plan').onclick=()=>{try{writePlanBook(unbindBookRoute(planBook,config.expedition));tell('已解除本路线绑定；保存的方案和当前草稿保留。');}catch(e){tell('解除失败：'+e.message);}};
$('#delete-plan').onclick=()=>{try{const id=$('#saved-plans').value,p=plans.find(p=>p.id===id);if(!p)throw Error('请先选择一个方案');const n=Object.values(planBook.bindings).filter(value=>value===id).length;if(!confirm('删除「'+p.name+'」？将解除'+n+'项路线绑定，当前草稿与公会资产保留。'))return;writePlanBook(deleteBookPlan(planBook,id));tell('已删除保存方案及其绑定，当前草稿与公会资产保留。');}catch(e){tell('删除失败：'+e.message);}};
mountPlanTransfer({storage:localStorage,onCommit:()=>{refreshPlanBook();renderPlans();renderAdventure();},notice:tell});
$('#load-plan').onclick=()=>{if(!refreshPlanBook()){tell(planBookError);return;}const p=plans.find(p=>p.id===$('#saved-plans').value);if(!p){tell('请先选择一个已保存方案。');return;}replaceConfig(p.config);scope='';persist();planner();tell('已载入「'+p.name+'」，可撤销本次载入。历史战报不变。');};
$('#undo-load').onclick=()=>{if(!undoConfig)return;try{const roles=Boolean(undoConfig.roles),prior=guildUI.undoConfiguration(undoConfig);config=prior.config;undoConfig=null;scope='';if(prior.persisted)savedState();else persist();planner();tell(roles?'已恢复载入前配置与本次改动的伙伴职责；当前训练、装备和其他公会资产保留。':'已恢复载入前的配置。');}catch(e){tell('无法撤销：'+e.message);}};
$('#report-to-a').onclick=()=>{if(!report)return;savedA=clone(report.config);try{localStorage.setItem(storageKey+'-a',JSON.stringify(savedA));}catch{}planner();tell('本次战报的出发配置已设为 A；当前编辑配置保持原样。');};
$('#restore-report').onclick=()=>{if(!report)return;replaceConfig(report.config);scope='';persist();planner();view('planning');tell('已恢复本战报的完整出发配置，可撤销。');};
function renderReview(){
 const rooms=reviewReport(report);$('#review-heading').textContent=EXPEDITIONS[report.config.expedition].name+' · 种子 '+report.config.seed;
 $('#review-rooms').innerHTML=rooms.map(r=>`<details class="review-room" ${r.roomIndex===0?'open':''}><summary>${esc(r.name)} · ${r.won?'通过':'止步'} · ${r.findings.length} 项观察</summary><div class="review-metrics"><span>实扣生命 <b>${r.metrics.damageTaken}</b></span><span>技能治疗 <b>${r.metrics.healing}</b></span><span>道具使用 <b>${r.metrics.items}</b></span><span>空过行动 <b>${r.metrics.failed}</b></span></div><div class="finding-list">${r.findings.map(f=>`<article class="finding ${f.kind}"><h3>${esc(f.title)}</h3><p>${esc(f.fact)}</p><p class="muted">尝试方向：${esc(f.suggestion)}</p><div><button data-evidence="${f.eventIndex}">定位原始事件</button>${f.hero?`<button data-review-edit="${f.roomId}:${f.hero}">从此战报修改 ${heroName(f.hero)}</button>`:''}</div></article>`).join('')||'<p class="muted">未发现当前规则覆盖的观察项；这不代表方案最优。</p>'}</div></details>`).join('');
}
function heroName(id){return HEROES.find(h=>h.id===id)?.name||id;}
$('#review-rooms').onclick=e=>{const evidence=e.target.closest('[data-evidence]'),edit=e.target.closest('[data-review-edit]');if(evidence){stop();replayWorkspace.open('evidence');$('#diagnostic').checked=true;renderJournal();move(Number(evidence.dataset.evidence));$('#detail').scrollIntoView({block:'start'});}else if(edit)editFromReport(edit.dataset.reviewEdit);};
function comparisonDetails(pair){
 const [a,b]=pair,changes=configurationChanges(a.config,b.config),ra=reviewReport(a),rb=reviewReport(b);
 const cell=(r,key)=>r?(key==='won'?(r.won?'通过':'失败'):key==='hp'||key==='mp'||key==='rounds'?r[key]:['herb','rune','arrow'].includes(key)?r.supplies[key]:r.metrics[key]):'未到达';
 return `<section class="comparison-detail"><h3>配置差异 · ${changes.length} 项</h3><p class="muted">展示上次运行的配置快照；修改配置后请重新对比。按共同种子比较，列出默认值和显式房间覆盖的变化。多个变化同时存在时，结果不能归因于某一个设置。</p>${changes.length?`<div class="table-scroll"><table><thead><tr><th>设置</th><th>A</th><th>B</th></tr></thead><tbody>${changes.map(c=>`<tr><th>${esc(c.label)}</th><td>${esc(c.before)}</td><td>${esc(c.after)}</td></tr>`).join('')}</tbody></table></div>`:'<p>两套配置完全相同。</p>'}${harborReserveComparison(a,b)}<h3>逐房间对照</h3><div class="room-comparison">${roomsFor(a.config).map((room,i)=>`<article><h3>${esc(a.rooms[i]?.name||room.name)}</h3>${a.rooms[i]?.name!==b.rooms[i]?.name?`<p>B：${esc(b.rooms[i]?.name||'未抵达')}</p>`:''}<table><thead><tr><th>观察项</th><th>A</th><th>B</th></tr></thead><tbody>${Object.entries({won:'结果',rounds:'回合',hp:'出房生命',mp:'出房法力',damageTaken:'实扣生命',items:'道具使用',failed:'空过行动',herb:'剩余药草',rune:'剩余符纸',arrow:'剩余箭矢'}).map(([key,label])=>`<tr><th>${label}</th><td>${cell(ra[i],key)}</td><td>${cell(rb[i],key)}</td></tr>`).join('')}</tbody></table></article>`).join('')}</div><p class="muted">出房生命与法力包含此前房间的影响；“实扣生命”只统计本房间正式队员承伤。未到达的房间不记为零。</p></section>`;
}
$('#case-shortage').onclick=()=>loadCase('shortage');

function trainingEditor(h,t,unit){const spent=trainingInvestment(h.training),attributes=attributeBreakdown(h);return `<section class="training-panel"><div class="bar"><h3>实验培养 <small>全局构筑</small></h3><strong>预计 ${spent}经验</strong><button id="clear-training">重置本角色训练</button></div><p class="muted">技能、防御与八项属性每项最高+${MAX_TRAINING_RANK}，逐级成本${trainingCostText}经验；无角色总点数硬上限。此处为实验草稿，不扣公会经验；真实出征采用公会实际培养。训练不随房间变化，战前倾向与专修仍可自由调整。</p><div class="training-grid">${Object.entries(trainingOptions(h.id)).map(([key,o])=>{const rank=h.training[key]||0,attribute=o.kind==='attribute',a=attribute?attributes.find(r=>r.key===o.id):null,spec=attribute?a.focus:(o.kind==='skill'?h.trained:h.defenseFocus)===o.id?3:0,equipment=attribute?0:equipmentRank(h.gear,key),level=attribute?a.total:t.base+spec+rank+equipment,disabled=rank>=MAX_TRAINING_RANK;return `<article class="training-row"><div><b>${esc(o.name)}</b><span>${attribute?'属性 · 出发总值':o.kind==='skill'?'职业技能 · 静态等级':'防御技能 · 静态等级'} ${level}</span><small>${attribute?`基础 ${a.base} + 倾向 ${a.focus} + 培养 ${rank} + 装备 ${a.equipment}${a.set!==undefined?' + 套装 '+a.set:''} · ${a.use}`:`基础 ${t.base} + 专修 ${spec} + 训练 ${rank}${equipment?' + 装备 '+equipment:''}${o.kind==='skill'?' · 检定均值 '+mean(unit,o.id):''}`}</small>${o.kind==='skill'&&SKILLS[o.id].requiresGear?'<small class="'+(gearSupports(h.gear,SKILLS[o.id].requiresGear)?'':'gear-warning')+'">需要 '+gearRequirementName(SKILLS[o.id].requiresGear)+'</small>':''}</div><div class="training-controls"><button data-training="${key}" data-delta="-1" ${rank===0?'disabled':''} aria-label="减少${o.name}训练">−</button><strong>+${rank}</strong><button data-training="${key}" data-delta="1" ${disabled?'disabled':''} aria-label="增加${o.name}训练">＋</button><small>${rank===MAX_TRAINING_RANK?'已达上限':'下一级 '+((rank+1)*TRAINING_XP_UNIT)+'经验'}</small></div></article>`;}).join('')}</div><p class="muted">以上为出发前静态值，装备已计入属性总值，临时效果另算。体质每点增加4生命上限、智力每点增加2法力上限、意志每点增加1法力上限，沿本原型已有公式；其他检定按原相关属性计算。固定数值技能不会因培养自动增强。</p></section>`;}
for(const kind of ['balanced','support','defense'])$('#build-'+kind).onclick=()=>{replaceConfig(trainingBuild(kind));scope='';persist();planner();view('planning');tell('训练方案已载入，包含潮汐异变战术。可撤销本次载入，或保存到方案册后继续调整。');};
$('#case-training').onclick=()=>loadCase('training');$('#case-pierce').onclick=()=>loadCase('pierce');

function renderIntel(){
 $('#escort-planning')?.remove();if(config.expedition==='evacuation')$('#intel').insertAdjacentHTML('beforebegin','<section id=escort-planning class=panel><h2>护送目标 · 后排90生命</h2><p>'+esc(ESCORT_RULE)+'</p></section>');
 $('#intel-route').textContent=EXPEDITIONS[config.expedition].name;
 $('#intel').innerHTML=focusPreparationView(config)+diseasePreparationView(config)+channelPreparationView(roomsFor(config),SKILLS,POS)+enemyThreatMapView(enemyThreatMap(config),{actual:false})+mechanismPreparationView(config)+wardPreparationView(roomsFor(config))+roomsFor(config).map((r,i)=>`<article class="encounter-card"><div class="encounter-heading"><small>ENCOUNTER 0${i+1}</small><h3>${esc(r.name)}</h3><span>${r.reinforcements?'首波'+r.enemies.length+'名 / 共'+roomWaves(r).length+'波公开敌情':r.enemies.length+' 名敌人 · '+new Set(r.enemies.map(e=>e.pos)).size+' 个阵位'}</span></div><p>${esc(r.note)}</p><div class="enemy-dossier">${roomWaves(r).map((wave,wi)=>`${r.reinforcements?`<h4>第${wi+1}波 · ${esc(wave.name)}</h4><p>${esc(wave.note)}</p>`:''}${wave.enemies.map(u=>`<details><summary><b>${esc(u.name)}</b><span>${POS[u.pos]} · ${u.maxHp} ${u.mechanism?'耐久':'HP'}</span></summary><div class="enemy-facts"><span>护甲 <b>${current(u,'armor')}</b></span>${Object.entries(TYPES).map(([k,v])=>{const n=resistanceOf(u,k);return `<span class="${n>0?'resist':n<0?'vulnerable':''}">${v} ${n<0?'弱点':'抗性'} <b>${Math.abs(n)}%</b></span>`;}).join('')}</div>${u.mechanism?`<p class=mechanism-label>${esc(mechanismLabel(u))}</p>`:''}${u.immuneTo?`<p class=immunity-label>${esc(immunityLabel(u))}</p>`:''}${healthPhasesView(u)}<p><small>预备：${u.prep.length?u.prep.map(r=>SKILLS[r.skill].name+scheduleLabel(r)+' · '+({once:'本房一次',round:'每回合一次',repeat:'持续',cycle:'轮转'}[r.mode])+' → '+(POS[r.target]||'自身')+' / 敌方'+commandCostText(u,r).replace('标准支付','独立支付').replace('无共享材料','无材料')).join('；'):'无'}${u.healing?.enabled?'<br>救护：'+esc(healingPlanDescription(u)):''}<br>普通：${u.main.map(r=>SKILLS[r.skill].name+scheduleLabel(r)+' · '+({once:'本房一次',round:'每回合一次',repeat:'持续',cycle:'轮转'}[r.mode])+' → '+POS[r.target]+' · 等级 '+u.skills[r.skill]+' / 均值 '+mean(u,r.skill)+' / 敌方'+commandCostText(u,r).replace('标准支付','独立支付').replace('无共享材料','无材料')).join('；')}</small></p></details>`).join('')}`).join('')}</div><button data-intel-room="${r.id}">配置这个房间</button></article>`).join('');
}
$('#intel').onclick=e=>{const threat=e.target.closest('[data-threat-edit]');if(threat){selected=threat.dataset.threatEdit;scope=threat.dataset.threatScope;planner();setPrep('team');$('#editor').scrollIntoView({block:'start'});tell('已定位草稿中该队友的本房站位与防御；尚未自动改配，请在公会核对实际配置。');return;}const b=e.target.closest('[data-intel-room]');if(b){scope=b.dataset.intelRoom;planner();setPrep('team');$('#editor').scrollIntoView({block:'start'});tell('已定位房间配置。训练、装备和补给仍为整次远征共用。');}};
$('#archive-start').onclick=()=>{replaceConfig(archiveConfig());scope='';persist();planner();view('planning');tell('已载入封库试炼的均衡方案。先展开敌情，再按房间调整目标和技能。');};
$('#case-archive').onclick=()=>loadCase('archive');

function renderBellPlan(){
 $('#bell-plan').hidden=!hasArchiveEvents(config);if(!hasArchiveEvents(config))return;
 const units=buildParty(config);$('#bell-options').innerHTML=Object.entries(BELL_CHOICES).map(([key,c])=>{const candidates=bellCandidates(units,key,mean);return `<button data-bell="${key}" aria-pressed="${config.bellApproach===key}"><strong>${c.name}</strong><span>${c.desc}</span><em>${BELL_ROUTES[key==='study'?'deciphered':key==='force'?'breach':'direct'].desc}</em>${candidates.length?`<small>出发前候选：${candidates.map(x=>HEROES.find(h=>h.id===x.id).name+' '+(x.reason||'均值'+x.mean)).join(' / ')}</small>`:''}</button>`;}).join('');
}
$('#bell-options').onclick=e=>{const b=e.target.closest('[data-bell]');if(b){config.bellApproach=b.dataset.bell;persist();planner();tell('沉钟机关策略已保存，抵达第二房间时根据实际存活与资源执行。');}};
$('#event-start').onclick=()=>{const c=archiveConfig();c.bellApproach='study';replaceConfig(c);scope='';persist();planner();view('planning');setPrep('events');$('#bell-plan').scrollIntoView({block:'start'});tell('已载入沉钟事件方案，可调整训练或机关策略后开始远征。');};
$('#case-bell').onclick=()=>loadCase('bell');

$('#route-consequence').onclick=e=>{const b=e.target.closest('[data-cause]');if(b){stop();move(report.events.findIndex(x=>x.id===Number(b.dataset.cause)));$('.stage').scrollIntoView({block:'start'});}};

function renderRescuePlan(){
 $('#rescue-plan').hidden=!hasArchiveEvents(config);if(!hasArchiveEvents(config))return;
 $('#rescue-options').innerHTML=Object.entries(RESCUE_CHOICES).map(([k,v])=>`<button data-rescue="${k}" aria-pressed="${config.rescueApproach===k}"><strong>${v.name}</strong><span>${esc(k==='gather'&&config.expedition==='scarcity'?'获得2药草；绕路占用1回合，第二房间由5回合缩短为4回合。':v.desc)}</span></button>`).join('');
 const healers=buildParty(config).filter(u=>u.skills.heal!==undefined).sort((a,b)=>mean(b,'heal')-mean(a,'heal'));
 $('#rescue-preview').textContent=healers.length?'出发前预览：'+healers[0].name+' · 治疗均值 '+mean(healers[0],'heal')+'。实际进场时由存活且治疗均值最高的药师执行；同值按出战顺序。':'当前出战队伍没有药师，无法执行救治。';
}
$('#rescue-options').onclick=e=>{const b=e.target.closest('[data-rescue]');if(b){config.rescueApproach=b.dataset.rescue;persist();planner();}};
$('#rescue-start').onclick=()=>{const c=archiveConfig();c.rescueApproach='aid';c.bellApproach='study';replaceConfig(c);scope='';persist();planner();view('planning');setPrep('events');$('#rescue-plan').scrollIntoView({block:'start'});tell('救援 → 沉钟 → 末房路线，已载入事件链方案。');};
$('#detail').onclick=e=>{const autoOrigin=e.target.closest('[data-automatic-origin]'),autoOutcome=e.target.closest('[data-automatic-outcome]');if(autoOrigin||autoOutcome){const g=groups.find(g=>index>=g.start&&index<=g.end),record=autoOrigin?g?.events.find(v=>v.detail.automaticAction):g?.events.find(v=>v.id===Number(autoOutcome.dataset.automaticOutcome)),at=autoOrigin?automaticOriginIndex(report,record,autoOrigin.dataset.automaticOrigin):automaticOutcomeIndex(report,record);if(at>=0){stop();move(at);}return;}const focus=e.target.closest('[data-focus-origin]');if(focus){const event=groups.find(g=>index>=g.start&&index<=g.end)?.events.find(v=>v.detail.focusTargeting?.followed?.effectId===focus.dataset.focusOrigin),at=focusOriginIndex(report,event);if(at>=0){stop();move(at);}return;}const channel=e.target.closest('[data-channel-origin]');if(channel){const event=groups.find(g=>index>=g.start&&index<=g.end)?.events.find(v=>v.detail.channel&&v.detail.channel.sourceEventId===Number(channel.dataset.channelOrigin)&&v.type!=='windup-start'),at=channelOriginIndex(report,event);if(at>=0){stop();move(at);}return;}const source=e.target.closest('[data-mana-regen-source]');if(source){const at=Number(source.dataset.manaRegenSource);if(!Number.isInteger(at)||!report.events[at])return;stop();manaRegenReturn=index;move(at);$('#detail').scrollIntoView({block:'center'});return;}if(e.target.closest('[data-mana-regen-return]')){const at=manaRegenReturn;manaRegenReturn=null;if(at!==null){stop();move(at);$('#detail').scrollIntoView({block:'center'});}return;}const mechanism=e.target.closest('[data-mechanism-outcome]');if(mechanism){const at=mechanismOutcomeIndex(report,report.events[index]);if(at<0||report.events[at].id!==Number(mechanism.dataset.mechanismOutcome))return;stop();mechanismReturn=index;move(at);return;}if(e.target.closest('[data-mechanism-return]')){const at=mechanismReturn;mechanismReturn=null;if(at!==null){stop();move(at);}return;}const immune=e.target.closest('[data-immunity-outcome]');if(immune){const source=report.events[index],at=immunityOutcomeIndex(report,source);if(at<0||report.events[at].id!==Number(immune.dataset.immunityOutcome))return;stop();immunityReturn=index;move(at);return;}if(e.target.closest('[data-immunity-return]')){const at=immunityReturn;immunityReturn=null;if(at!==null){stop();move(at);}return;}const pos=e.target.closest('[data-position-outcome]');if(pos){const source=report.events[index],at=positionOnlyOutcomeIndex(report,source);if(at<0||report.events[at].id!==Number(pos.dataset.positionOutcome))return;stop();positionReturn=index;move(at);$('#detail').scrollIntoView({block:'start'});return;}if(e.target.closest('[data-position-return]')){const at=positionReturn;positionReturn=null;if(at!==null){stop();move(at);}return;}const count=e.target.closest('[data-count-outcome]');if(count){const at=report.events.findIndex(x=>x.id===Number(count.dataset.countOutcome));if(at<0)return;stop();scheduleReturn=index;move(at);$('#detail').scrollIntoView({block:'start'});return;}const schedule=e.target.closest('[data-schedule-outcome]');if(schedule){const at=report.events.findIndex(x=>x.id===Number(schedule.dataset.scheduleOutcome));if(at<0)return;stop();scheduleReturn=index;move(at);$('#detail').scrollIntoView({block:'start'});return;}if(e.target.closest('[data-schedule-return]')){const at=scheduleReturn;scheduleReturn=null;if(at!==null){stop();move(at);}return;}const manaFloor=e.target.closest('[data-mana-floor-outcome]');if(manaFloor){const at=report.events.findIndex(x=>x.id===Number(manaFloor.dataset.manaFloorOutcome));if(at<0)return;stop();scheduleReturn=index;move(at);$('#detail').scrollIntoView({block:'center'});return;}const stock=e.target.closest('[data-stock-outcome]');if(stock){stop();move(report.events.findIndex(x=>x.id===Number(stock.dataset.stockOutcome)));return;}const b=e.target.closest('[data-rescue-cause]');if(b){stop();move(report.events.findIndex(x=>x.id===Number(b.dataset.rescueCause)));$('#rescue-result').scrollIntoView({block:'start'});}};

function setPrep(tab){
 prepTab=tab;document.querySelectorAll('[data-prep-panel]').forEach(p=>p.hidden=p.dataset.prepPanel!==tab);document.querySelectorAll('[data-prep]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.prep===tab)));
 $('#hospice-brief').hidden=config.expedition!=='hospice';$('#scarcity-brief').hidden=config.expedition!=='scarcity';$('#survival-brief').hidden=config.expedition!=='survival';
 $('#no-events').hidden=hasArchiveEvents(config)||config.expedition==='harbor';
}
document.querySelector('.prep-tabs').onclick=e=>{const b=e.target.closest('[data-prep]');if(b)setPrep(b.dataset.prep);};
function renderDeparture(){
 const isChapter=config.expedition==='chapter',isArchive=hasArchiveEvents(config),units=buildParty(config),b=BELL_CHOICES[config.bellApproach];
 $('#departure-overview').innerHTML=`<p class="eyebrow">出发计划 / ${esc(EXPEDITIONS[config.expedition].name)}</p><h2>先看整条远征，再分配每一份资源。</h2><div class="departure-cards"><article><small>01 · 携带补给</small><h3>${config.supplies.herb} 药草 / ${config.supplies.rune} 符纸 / ${config.supplies.arrow} 箭矢</h3><p>房间之间延续生命、法力与物资。</p><button data-prep-jump="team">配置队伍与补给 →</button></article><article><small>02 · 回廊事件</small><h3>${config.expedition==='courier'?COURIER_PASSES[courierPass(config)]:config.expedition==='harbor'?HARBOR_PASS[config.harbor.pass]+' → '+HARBOR_TASK[config.harbor.task]:isArchive?RESCUE_CHOICES[config.rescueApproach].name+' → '+b.name:'本路线无回廊事件'}</h3><p>${config.expedition==='courier'?'第二场通路在上方邮路简介中选择；船底抵达时花2箭矢，不足走分舱。':isArchive?'先救援，所得物资可用于沉钟；检定使用实际进场状态。':'按各场敌情配置技能、阵位与协作顺序。'}</p><button data-prep-jump="events">查看事件策略 →</button></article><article><small>03 · ${isChapter?'封库出口与下半章':'最终遭遇'}</small><h3>${config.expedition==='courier'?(courierPass(config)==='keel'?'实际船底通路 → 断令回邮台':'折帆分舱 → 封蜡回邮台'):isArchive?(config.bellApproach==='study'?'成功解读 → 破印路线':config.bellApproach==='force'?'成功破拆 → 侧门路线':'按计划走正门'):'按敌情进入末房'}</h3><p>${isArchive?(isChapter?'成功改变第三场封库出口；之后仍须带着剩余资源走完三场疗所遭遇。':'只有成功才改变末房；失败、缺料或无执行者仍走正门。'):'保留足够补给，避免末房空过行动。'}</p><button data-prep-jump="plans">管理完整方案 →</button></article></div><p class="muted">当前药师治疗均值 ${units.some(u=>u.skills.heal!==undefined)?Math.max(...units.filter(u=>u.skills.heal!==undefined).map(u=>mean(u,'heal'))):'无可用药师'}。这里只展示出发计划，不预测实际成功或改写已有战报。</p>`;
}
$('#departure-overview').onclick=e=>{const b=e.target.closest('[data-prep-jump]');if(b)setPrep(b.dataset.prepJump);};
function renderChain(){
 const kinds={rescue:'救援与补给',encounter:'沉钟检定',route:report.config.expedition==='chapter'?'封库出口':'末房路线'},actual=Object.entries(kinds).map(([type,label])=>({type,label,event:report.events.find(e=>e.type===type)}));
 $('#chain-summary').hidden=!hasArchiveEvents(report.config);
 $('#chain-summary').innerHTML='<p class="eyebrow">本次远征 / 已发生的事件链</p><div class="departure-cards">'+actual.map(({label,event})=>`<article><small>${label}</small><h3>${event?esc(event.text):'未到达'}</h3><p>${event?esc(event.detail.rule):'未记录该事件，不按失败或零收益处理。'}</p>${event?`<button data-chain-id="${event.id}">查看此事件 →</button>`:''}</article>`).join('')+'</div><small>此处为完整结算结果，可能提前显示尚未播放的事件。</small>';
}
$('#chain-summary').onclick=e=>{const b=e.target.closest('[data-chain-id]');if(b){stop();move(report.events.findIndex(x=>x.id===Number(b.dataset.chainId)));(!$('#rescue-result').hidden?$('#rescue-result'):!$('#route-consequence').hidden?$('#route-consequence'):$('#event-scene')).scrollIntoView({block:'start'});}};
function renderSamples(){
 if(!sampleData)return;const rows=sampleData.rows.filter(r=>r.profile===$('#sample-profile').value);
 $('#sample-table').innerHTML='<div class="table-scroll"><table><thead><tr><th>救援 / 沉钟</th><th>通过</th><th>救治成功/执行</th><th>沉钟成功/执行</th><th>剩余HP</th><th>药草</th><th>符纸</th><th>箭矢</th></tr></thead><tbody>'+rows.map(r=>{const v=r.summary;return `<tr><th>${RESCUE_CHOICES[r.rescue].name}<br><small>${BELL_CHOICES[r.bell].name}</small></th><td>${v.wins}/${v.count}</td><td>${v.rescueSuccess}/${v.rescueAttempts}</td><td>${v.bellSuccess}/${v.bellAttempts}</td><td>${v.hp}</td><td>${v.herb}</td><td>${v.rune}</td><td>${v.arrow}</td></tr>`;}).join('')+'</tbody></table></div>';
}
$('#sample-profile').onchange=renderSamples;
fetch('samples-v13.json').then(r=>{if(!r.ok)throw Error('读取失败');return r.json();}).then(data=>{if(data.ruleset!==RULESET)throw Error('样本规则版本不匹配');sampleData=data;renderSamples();}).catch(()=>{$('#sample-table').textContent='样本暂时无法读取；仍可使用上方单种子A/B对照。';});

