$('#pressure-profile').onchange=renderPressure;
fetch('samples-v14.json').then(r=>{if(!r.ok)throw Error('读取失败');return r.json();}).then(d=>{if(d.ruleset!==RULESET)throw Error('样本规则版本不匹配');pressureData=d;renderPressure();}).catch(()=>{$('#pressure-table').textContent='挑战样本读取失败；可在下方使用A/B对照。';});

function renderSettlement(){
 const contract=contractResult(report);$('#contract-outcome').hidden=!contract;if(contract)$('#contract-outcome').innerHTML=`<p class=eyebrow>疗所委托 / 完整结算</p><h2>${contract.handoff?'药箱按时抵岸，六人一同归来。':contract.cargo?'物资完整归航，交接稍晚。':'远征已结算，封存目标尚未完成。'}</h2><div class=departure-cards><article><h3>封存物资 ${contract.cargo?'✓':'未达成'}</h3><p>符纸 ${report.supplies.rune}/4 · 箭矢 ${report.supplies.arrow}/4 · ${contract.alive}/6 人存活</p></article><article><h3>准时交接 ${contract.handoff?'✓':'未达成'}</h3><p>三房累计 ${contract.rounds}/15 回合；须同时完成封存目标。</p></article></div><button data-contract=opening>调整为每房开场爆发</button><p class=muted>此处为完整结算，不随回放变化。下方战场任务条只显示播放到当前事件时的情况。委托暂不发放成长奖励。</p>`;
 const ledger=supplyLedger(report);
 $('#settlement').innerHTML='<p class="eyebrow">完整远征结算 / 包含尚未播放的结果</p><div class="departure-cards">'+settlementGoals(report).map(g=>`<article class="goal ${g.done?'achieved':''}"><small>${g.done?'已达成':'未达成'}</small><h3>${g.name}</h3><p>${g.rule}</p></article>`).join('')+'</div><h3>共享补给收支</h3><table><thead><tr><th>物资</th><th>出发</th><th>获得</th><th>消耗</th><th>剩余</th></tr></thead><tbody>'+ledger.rows.map(r=>`<tr><td>${r.name}</td><td>${r.start}</td><td>+${r.gained}</td><td>−${r.spent}</td><td>${r.end}</td></tr>`).join('')+'</tbody></table><p class="muted">出发＋获得−消耗＝剩余。仅统计共享物资，不含法力或随身道具次数。目标无成长奖励，物资不会带入下次远征。</p><details><summary>逐笔变动 · '+ledger.entries.length+' 条（点击追溯战报）</summary><div class="ledger-entries">'+ledger.entries.map(x=>`<button data-ledger-event="${x.eventId}"><small>${x.roomIndex+1}房 / 回合${x.round} · ${x.changes.map(c=>c.name+' '+(c.delta>0?'+':'')+c.delta).join(' / ')}</small><span>${esc(x.text)}</span></button>`).join('')+'</div></details>';
}
$('#settlement').onclick=e=>{const b=e.target.closest('[data-ledger-event]');if(b){stop();move(report.events.findIndex(x=>x.id===Number(b.dataset.ledgerEvent)));$('.stage').scrollIntoView({block:'start'});}};

let reserveData=null;
$('#reserve-seed').innerHTML=Array.from({length:32},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('');
function renderReserve(){
 if(!reserveData)return;
 const seed=Number($('#reserve-seed').value),rows=reserveData.rows.filter(r=>r.rescue===$('#reserve-rescue').value);
 $('#reserve-table').innerHTML='<div class="table-scroll"><table><thead><tr><th>携带 / 普通指令</th><th>通关</th><th>全员归航</th><th>储备达标</th><th>全部达成</th><th>通关平均余量<br>草 / 符 / 箭</th><th>所选种子实际结果</th><th>试玩</th></tr></thead><tbody>'+rows.map(r=>{const v=r.summary,x=r.samples.find(x=>x.seed===seed),stock=x.won&&x.supplies.rune>=2&&x.supplies.arrow>=2;return `<tr><th>${LOADOUTS[r.loadout].name} ${Object.values(LOADOUTS[r.loadout].supplies).join('/')}<br><small>${POLICIES[r.policy]}</small></th><td>${v.wins}/${v.count}</td><td>${v.survive}/${v.count}</td><td>${v.reserve}/${v.count}</td><td><b>${v.all}/${v.count}</b></td><td>${Object.values(v.winSupplies).map(n=>n??'—').join(' / ')}</td><td>${x.won?'通关':'失败'} · ${x.survivors}人生还<br><small>余量 ${Object.values(x.supplies).join('/')} · ${stock?'储备达标':'储备未达标'}</small></td><td><button data-reserve-load="${r.loadout}" data-reserve-policy="${r.policy}">载入方案</button></td></tr>`;}).join('')+'</tbody></table></div>';
}
$('#reserve-rescue').onchange=renderReserve;$('#reserve-seed').onchange=renderReserve;
$('#reserve-table').onclick=e=>{const b=e.target.closest('[data-reserve-load]');if(!b)return;replaceConfig(reserveConfig(b.dataset.reserveLoad,b.dataset.reservePolicy,$('#reserve-rescue').value,Number($('#reserve-seed').value)));scope='';persist();planner();view('planning');setPrep('overview');$('#departure-overview').scrollIntoView({block:'start'});tell('已载入完整实验方案和所选种子；点击开始远征复现。方案管理可撤销本次载入。');};
fetch('samples-v16.json').then(r=>{if(!r.ok)throw Error('读取失败');return r.json();}).then(d=>{if(d.ruleset!==RULESET)throw Error('样本规则版本不匹配');reserveData=d;renderReserve();}).catch(()=>{$('#reserve-table').textContent='储备样本暂时无法读取；已有战术实验与远征仍可使用。';});

function loadSurvival(kind){replaceConfig(survivalConfig(kind));savedA=survivalConfig('baseline');try{localStorage.setItem(storageKey+'-a',JSON.stringify(savedA));}catch{}scope='';persist();planner();view('planning');setPrep('overview');$('#departure-overview').scrollIntoView({block:'start'});$('#a-state').textContent='A：守灯原始队形 · 对比共用当前种子';tell('已载入守灯方案，原始队形已设为A；可开始远征或在战术实验对照。');}
$('#survival-start').onclick=()=>loadSurvival('baseline');$('#survival-brief').onclick=e=>{const b=e.target.closest('[data-survival]');if(b)loadSurvival(b.dataset.survival);};
function renderSurvivalOutcome(){
 $('#survival-outcome').hidden=report.config.expedition!=='survival';if(report.config.expedition!=='survival')return;
 const downs=report.events.filter(e=>e.type==='down'&&HEROES.some(h=>e.targets.includes(h.id))),healing=healingActivity(report);
 $('#survival-outcome').innerHTML='<p class="eyebrow">守灯结算 / 完整结果</p><h2>'+ (report.won?(downs.length?'灯火守住了，但有人未能归队。':'灯火与六名队员，一同归来。'):'归途尚未走完。')+'</h2><p>药师实际治疗 '+healing.actual+' 生命 / 普通救护 '+healing.ordinaryActions+' 次行动 / 缓释 '+healing.passiveRecords+' 条目标恢复记录。以下倒下记录可回到当次受击；治疗总量不能单独证明方案更好。</p>'+downs.map(e=>`<button data-down-event="${e.id}">${esc(HEROES.find(h=>h.id===e.targets[0])?.name||e.text)} · ${e.roomIndex+1}房 / 第${e.round}回合倒下 →</button>`).join('')+'<p class="muted">先比较攻击覆盖、防御与救护时机。此处为完整结算，不随播放进度变化。</p>';
}
$('#survival-outcome').onclick=e=>{const b=e.target.closest('[data-down-event]');if(b){stop();const at=report.events.findIndex(x=>x.id===Number(b.dataset.downEvent));selectedUnit=report.events[at].targets[0];move(at);$('#care-panel').open=true;$('#care-panel').scrollIntoView({block:'start'});}};

function renderCare(){
 const timeline=careTimeline(report,selectedUnit,selectedGroup().events.at(-1).id);$('#care-panel').hidden=!timeline;if(!timeline)return;
 $('#care-timeline').innerHTML=`<h3>${esc(timeline.unit)} · 当前 HP ${timeline.hp}/${timeline.maxHp}</h3><p class="muted">只显示当前房间、截至当前回放快照的最近12条记录（已发生${timeline.total}条）。药师行动穿插其中；有决策记录的行动会列出当时阈值、范围和资源；未记录的行动不推测原因。点击记录可回到该行动。</p><div class="care-list">${timeline.rows.map(x=>`<button class="care-${x.kind}" data-care-event="${x.eventId}"><small>第${x.round}回合 · ${esc(x.phase)} · ${({damage:'受击与防御',heal:'生命恢复',down:'倒下',medic:'药师行动'})[x.kind]}</small><b>${esc(x.text)}</b><span>${esc(x.detail)}</span></button>${x.decision?healingMarkup(x.decision):''}`).join('')||'<p>此时尚无受击、恢复或药师行动记录。</p>'}</div><small>行动合并模式跳转到整次施放的最终快照；逐条诊断模式可查看单条记录。</small>`;
}
$('#care-timeline').onclick=e=>{const b=e.target.closest('[data-care-event]');if(b){stop();move(report.events.findIndex(x=>x.id===Number(b.dataset.careEvent)));$('#care-panel').open=true;$('#care-panel').scrollIntoView({block:'start'});}};

function healingBlockMarkup(block){const origin=block?originMap.get(block.effectId):null,canTrace=origin&&origin.source===block.source&&origin.targets.includes(block.target)&&origin.index<index,roomId=canTrace?roomsFor(report.config)[report.events[origin.index].roomIndex]?.id:null,canEdit=roomId&&report.config.heroes.some(h=>h.id===block.source);return `<p class="healing-block-proof">禁疗仅限制本回合余下的自动草药救护；不会撤销已完成治疗，也不会阻止普通指令。${canTrace?`<button data-healing-origin="${origin.index}">查看禁疗命中来源 →</button>`:''}${canEdit?`<button data-healing-edit="${roomId}:${block.source}">调整本房截疗指令 →</button><small>改配用于准备页与A/B实验；公会仍按已应用伙伴职责执行，请核对实际指令。</small>`:''}</p>`;}
function healingMarkup(d,actor){
 const skipped=d.status==='item_priority',stockLabel=report.events[index].units.find(u=>u.id===actor)?.side==='enemy'?'敌方独立库存':'本方共享库存';

 return `<section class="healing-decision"><h4>治疗决策 · ${esc(healingReason(d))}</h4>${d.status==='blocked'?healingBlockMarkup(d.block):''}<p>策略：${esc(HEAL_PRIORITIES[d.selectionPolicy||'lowest'])}。行动开始：MP ${d.mp} / 需要${d.cost.mp} · ${stockLabel}药草 ${d.herb} / 需要${d.cost.herb} · 阈值 ${Math.round(d.threshold*100)}% · 范围 ${esc(POS[d.target]||({all:'全队',self:'自身'}[d.target])||d.target)}</p>${skipped?'':groupAidEvidenceView(d)}${skipped?'<p>道具优先并占用行动；以下治疗候选未参与本次决策。</p>':`<div class="table-scroll"><table><thead><tr><th>队员</th><th>检查时生命</th><th>生命比例</th><th>资格</th></tr></thead><tbody>${d.candidates.map(x=>`<tr><th>${esc(x.name)}${x.id===d.selectedId?' · 优先候选':''}</th><td>${x.hp}/${x.maxHp}</td><td>${(x.ratio*100).toFixed(1)}%</td><td>${esc(x.reason)}</td></tr>`).join('')}</tbody></table></div><small>${esc(d.priority)}${!d.enabled?' 自动治疗关闭时以上仅为状态快照，不执行选择。':''}</small>`}</section>`;
}

$('#heal-priority-case').onclick=()=>{loadSurvival('baseline');config.heroes.find(h=>h.id==='f').healing.priority='self_first';persist();planner();tell('A为最低生命比例，B仅改为优先自保；种子1，其他配置相同。请在战术实验对比。');};

function loadHospice(kind){replaceConfig(hospiceConfig(kind));savedA=hospiceConfig('front');try{localStorage.setItem(storageKey+'-a',JSON.stringify(savedA));}catch{}scope='';persist();planner();view('planning');setPrep('overview');$('#departure-overview').scrollIntoView({block:'start'});$('#a-state').textContent='A：疗所正面方案 · 对比共用当前种子';tell('已载入疗所方案；先看敌情，再开始远征。正面方案已设为A。');}
$('#hospice-start').onclick=()=>loadHospice('front');$('#hospice-brief').onclick=e=>{const b=e.target.closest('[data-hospice]');if(b)loadHospice(b.dataset.hospice);};

function preserveObjective(next){return config.expedition===next.expedition&&config.objective?withObjective(next,config.objective):next;}
function loadContract(kind){replaceConfig(preserveObjective(contractPlan(kind)));savedA=contractPlan('sustained');try{localStorage.setItem(storageKey+'-a',JSON.stringify(savedA));}catch{}scope='';persist();planner();view('planning');setPrep('overview');$('#departure-overview').scrollIntoView({block:'start'});$('#a-state').textContent='A：持续集火 · 对比共用当前种子';tell('已载入封存交接方案，持续集火已设为A；技能频率与防护覆盖需要一并权衡。');}
$('#hospice-brief').addEventListener('click',e=>{const b=e.target.closest('[data-contract]');if(b)loadContract(b.dataset.contract);});
$('#contract-outcome').onclick=e=>{const b=e.target.closest('[data-contract]');if(b)loadContract(b.dataset.contract);};

$('#role-hunt').onclick=e=>{const b=e.target.closest('[data-hunt]');if(!b)return;replaceConfig(roleHuntConfig(b.dataset.hunt));savedA=roleHuntConfig('summoner');try{localStorage.setItem(storageKey+'-a',JSON.stringify(savedA));}catch{}scope='';persist();planner();view('planning');setPrep('overview');$('#a-state').textContent='A：先召唤者 · 对比共用当前种子';tell('职责猎杀已载入；无对应职责或资源不足时按顺序尝试后续指令。');};

function renderDeployment(){
 const v=deploymentPreview(config,scope),coverage=v.coverage.find(x=>x.id===coverageId)||v.coverage[0],active=v.units.find(u=>u.id===selected),roomInfo=roomsFor(config).find(r=>r.id===scope);
 if(coverage)coverageId=coverage.id;
 $('#deployment').innerHTML=`<div class="bar"><div><p class=eyebrow>部署桌 / 站位与协作覆盖</p><h2>把队员放在能相互照应的位置。</h2></div><label>编辑范围<select id="deploy-scope"><option value="">默认方案</option>${roomsFor(config).map(r=>`<option value="${r.id}" ${r.id===scope?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label></div><p>${roomInfo?esc(roomInfo.note):'默认站位供未单独覆盖的房间继承。切换房间可查看该房间实际采用的配置。'}</p><div class="deployment-layout"><div><div class="deploy-selection">已选 <strong>${esc(active.name)}</strong> · ${POS[active.pos]} · ${active.overridden?'本房覆盖':scope?'继承默认':'默认站位'} ${active.overridden?'<button data-inherit="pos">恢复默认站位</button>':''}<span>点击队员选中，再点击阵位下方的部署按钮。</span></div><div class="deployment-board">${Object.entries(POS).map(([pos,label])=>`<section class="deploy-zone deploy-${pos}"><div class="bar"><strong>${label}</strong><small>${v.units.filter(u=>u.pos===pos).length} 人</small></div><div class="deploy-units">${v.units.filter(u=>u.pos===pos).map(u=>`<button data-hero="${u.id}" class="deploy-unit ${selected===u.id?'selected':''} ${coverage?.recipients.includes(u.id)?'covered':''}" aria-pressed="${selected===u.id}" aria-label="选择${esc(u.name)}"><span class="portrait ${portrait(u)}" aria-hidden="true"></span><b>${esc(u.name)}</b><small>${u.overridden?'房间覆盖':'默认'}${coverage?.recipients.includes(u.id)?' · 可覆盖':''}</small></button>`).join('')||'<small class="muted">暂无队员</small>'}</div><button class="deploy-place" data-deploy="${pos}" ${active.pos===pos?'disabled':''}>部署至${label}</button></section>`).join('')}</div></div><aside class="coverage-preview"><h3>辅助覆盖候选</h3><p class="muted">点击一条预备指令，高亮其可覆盖的正式队员。</p>${v.coverage.map(x=>`<button data-coverage="${x.id}" aria-pressed="${coverage?.id===x.id}"><strong>${esc(x.name)} · ${SKILLS[x.skill].name}</strong><small>预备第${x.row+1}条 → ${POS[x.target]||({self:'自身',all:'全队',supportPriority:'辅助阵位优先'}[x.target])} · ${x.recipients.length} 人</small></button>`).join('')||'<p>当前未配置辅助技能。</p>'}<div class="coverage-result" aria-live="polite"><strong>${coverage?SKILLS[coverage.skill].name:'无辅助指令'}</strong><p>${coverage?.recipients.length?coverage.recipients.map(id=>HEROES.find(h=>h.id===id).name).join('、'):'没有覆盖候选'}</p>${coverage?.dynamicSupportOrder?`<p>初次顺序：${esc(coverage.dynamicSupportOrder)}；后续按未覆盖与效果结束重新检查，此处不预演整场轮转。</p>`:''}</div><small>按出发时全员存活、无临时效果计算；同位置上限按技能规则。不模拟指令轮转、材料、法力、同名效果互斥或后续召唤物，不保证实际施放成功。</small></aside></div><div class="deploy-order"><span>回合前顺序</span>${v.order.map((id,i)=>`<button data-hero="${id}">${i+1} · ${HEROES.find(h=>h.id===id).name}</button>`).join('')}</div><p class="muted">阵位是逻辑分组，不代表距离。普通行动先攻另行检定；辅助先后顺序在下方调整。移动不会改写已经生成的战报。</p>`+cooperationView(cooperationCheck(config,scope));
}

function focusCommandRow(value,phase='prep'){if(value===undefined||!['prep','main'].includes(phase))return;const row=Number(value);if(!Number.isInteger(row)||row<0)return;const field=$('#editor select[data-phase="'+phase+'"][data-row="'+row+'"][data-field="skill"]');field?.focus();}
$('#deployment').addEventListener('click',e=>{const b=e.target.closest('[data-cooperation-edit]');if(!b)return;selected=b.dataset.cooperationEdit;scope=b.dataset.cooperationRoom;planner();$('#editor').scrollIntoView({block:'start'});focusCommandRow(b.dataset.cooperationRow,b.dataset.cooperationPhase||'prep');tell('正在调整协作提示对应的队员与房间；尚未自动改动指令。');});

function routeAssignmentView(route){if(planBookError)return '';const p=plans.find(p=>p.id===planBook.bindings[route]);return p?`<p class=route-assignment data-route-bound="${route}">下次准备使用「${esc(p.name)}」</p>`:'';}
function renderAdventure(){refreshPlanBook();
 $('#adventure').innerHTML=`<div class="adventure-heading"><p class=eyebrow>海岸营地 / 沉没修道院</p><h1>潮水之下，仍有人等待归来。</h1><p>决定去往何处，准备六人的战术，把他们带回来。</p><p class=route-focus-policy>未分配完整方案的路线沿用本人的战前倾向、技能专修与防御专修；阵位和指令采用新路线起点。已分配的完整方案优先。明确载入完整战术起点、文件或历史时，采用其中的人物设置。</p><button id="resume-preparation" class="primary">继续准备 · ${EXPEDITIONS[config.expedition].name}</button>${report?`<button id="last-report">上次战报 · ${report.won?'通关':'止步'}</button>`:''}</div><section class="panel solo-journey-entry"><p class="eyebrow">单人旅程 / 远征之后的故事</p><h2>带回胜利，也带回一封回信。</h2><p>从沉钟下走向灯塔，或替铸库最后一班写下归航的名字。实际远征成果串成故事，也可沿钟楼、书库与温室的攻略继续潮刻余响；前三段旅程复用已有成果；归信航程需接取后按顺序选择两段通路，再把信送抵回邮台。</p><div class="bar"><button data-open-journey="harbor">灯塔来信 →</button><button data-open-journey="foundry">铸库归航 →</button><button data-open-journey="clocktower">潮刻余响 →</button><button data-open-journey="postquest">归信航程 · 分支任务 →</button></div></section>${campMapView()}<div class="adventure-map">${ADVENTURE_GROUPS.map(group=>`<section class="adventure-group" data-adventure-group="${group.id}"><h2>${group.title}</h2><p>${group.text}</p><div class="adventure-group-cards">${group.routes.map(id=>ADVENTURES.find(a=>a.id===id)).map(a=>`<article class="adventure-card ${a.id==='chapter'?'chapter-card':''}" style="--card-art:url('assets/${a.image}')"><div><p class=eyebrow>${a.tag}</p><h2>${a.title}</h2><p>${a.desc}</p><small>${a.focus}</small>${routeAssignmentView(a.id)}<details class="route-rewards"><summary>公会奖励与装备来源</summary><p>${rewardPreview(a.id)}</p></details><button data-adventure="${a.id}">准备${a.id==='tutorial'?'首次出征':a.id==='chapter'?'章节远征':'这条路线'} →</button></div></article>`).join('')}</div></section>`).join('')}</div><p class=muted>分区按体验主题，不是难度或胜率排序。所有路线均可直接体验。选择路线载入对应准备方案，可撤销；公会出征可获得永久成长，实验试跑不发奖励。</p>`;
}
function renderGuide(){
 const tutorial=config.expedition==='tutorial';$('#first-guide').hidden=!tutorial||guideDismissed;if(!tutorial)return;
 $('#first-guide').innerHTML=`<p class=eyebrow>首次出征 / 一场真实战斗</p><h2>先看敌情，再决定谁保护谁。</h2><div class=departure-cards><article><h3>1 · 看敌情</h3><p>前排重卫挡住近战，后排弩手可被远程优先攻击。</p><button data-guide=intel>查看敌人</button></article><article><h3>2 · 看协作</h3><p>吟游者先启蒙，学者再施放屏障。可以在部署桌检查覆盖。</p><button data-guide=team>查看队伍</button></article><article><h3>3 · 出征与复盘</h3><p>不要求先改配置。核对实际公会队伍后正式出征，再复盘并领取永久成长收益。</p><button data-guide=run>核对首次正式出征 →</button></article></div><button data-guide=skip class=link>收起引导</button>`;
}
function renderHeroBuilds(){
 const h=HEROES.find(h=>h.id===selected);$('#hero-builds').innerHTML=`<p class=eyebrow>角色构筑 / ${h.name} · ${h.role}</p><h2>为这次冒险选择职责</h2><div class=build-options>${BUILDS[selected].map(b=>`<article><h3>${b.name}</h3><p>${b.desc}</p><small>${equipmentName(b.gear)} · 护甲${equipmentTotals(b.gear).armor} · ${Object.entries(equipmentTotals(b.gear).bonus).map(([k,v])=>ATTR[k]+(v>0?'+':'')+v).join(' / ')}<br>专修 ${SKILLS[b.trained].name} · 培养成本 ${trainingInvestment(b.training)}经验</small><button data-build="${b.id}">应用${b.name}</button></article>`).join('')}</div><small>只改变当前队员；应用会清除该队员各房间的预备、普通指令和治疗覆盖，保留站位、防御与道具配置。可在方案管理撤销。</small>`;
}
function renderJourneyResult(){
 $('#harbor-assessment').hidden=report.config.expedition!=='harbor';$('#harbor-assessment').innerHTML=harborAssessmentView(report);
 $('#foundry-outcome').hidden=!['greenhouse','scriptorium','palisade','inquest','shoals','theater','foundry','foundrywatch','courier'].includes(report.config.expedition);$('#foundry-outcome').innerHTML=foundryOutcomeView(report);
 const ending=chapterEnding(report);$('#chapter-ending').hidden=!ending;if(ending)$('#chapter-ending').innerHTML=`<img src="assets/${ending.image}" alt="远征归途场景示意"><div><p class=eyebrow>${report.config.expedition==='breakwater'?'潮堤接应':report.config.expedition==='counterpoint'?'错拍回廊':report.config.expedition==='confluence'?'合流救护站':report.config.expedition==='greenhouse'?'蚀潮温室':report.config.expedition==='scriptorium'?'逆印书库':report.config.expedition==='palisade'?'折潮哨垒':report.config.expedition==='shoals'?'漂流群礁':report.config.expedition==='theater'?'失声剧场':report.config.expedition==='courier'?'邮路支线':report.config.expedition==='harbor'?'第二章':['foundry','foundrywatch'].includes(report.config.expedition)?'铸库支线':'第一章'} / 完整结算</p><h2>${esc(ending.title)}</h2><p>${esc(ending.text)}</p><small>画面为场景示意；队员存亡以战报为准。物资不带入下一次远征。</small></div>`;
 const evidence=report.events.find(e=>e.type==='effect'&&e.detail.skill==='ward')||report.events.find(e=>e.type==='attack');
 $('#next-actions').innerHTML=`<div class=bar><strong>${report.config.expedition==='tutorial'?'首次出征结束：接着看一条实际行动。':'完成复盘后，可以调整战术再试。'}</strong><div>${evidence?`<button data-journey-evidence="${evidence.id}">查看${report.config.expedition==='tutorial'?'协作依据':'关键行动'}</button>`:''}<button data-replay-pane="review">查看我的远征表现</button><button data-journey=retry>按本次配置调整</button><button data-journey=map>返回冒险地图</button></div></div>`;
}
$('#adventure').onclick=e=>{try{const b=e.target.closest('button');if(!b)return;if(b.dataset.cycleAction){guildUI.cycle(b.dataset.cycleAction,b.dataset.cycleValue||'');}else if(b.hasAttribute('data-open-journey')){guildUI.open('journey',b.dataset.openJourney||'foundry');}else if(b.dataset.adventure){const assigned=routeFocusPreparation(localStorage,b.dataset.adventure,config,readCycleGuild(localStorage));replaceConfig(assigned.config);scope='';guideDismissed=false;persist();planner();view('planning');setPrep('overview');window.scrollTo({top:0,behavior:'smooth'});tell((assigned.plan?'已载入本路线分配的「'+assigned.plan.name+'」；实际资产与伙伴职责仍以公会核对为准。':'路线准备方案已载入。')+routeFocusNotice(assigned));}else if(b.id==='resume-preparation'){view('planning');setPrep('overview');}else if(b.id==='last-report')view('replay');}catch(error){tell('准备未改变：'+error.message);}};
$('#first-guide').onclick=e=>{const b=e.target.closest('[data-guide]');if(!b)return;if(b.dataset.guide==='skip'){guideDismissed=true;renderGuide();}else if(b.dataset.guide==='run')$('#guild-run').click();else if(b.dataset.guide==='team'){setPrep('team');$('#deployment').scrollIntoView({block:'start'});}else{setPrep('overview');$('#intel').scrollIntoView({block:'start'});}};
$('#next-actions').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.journeyEvidence){move(report.events.findIndex(x=>x.id===Number(b.dataset.journeyEvidence)));$('#detail').scrollIntoView({block:'start'});}else if(b.dataset.journey==='map'){renderAdventure();view('adventure');window.scrollTo({top:0});}else if(b.dataset.journey==='retry'){replaceConfig(report.config);scope='';persist();planner();view('planning');setPrep('team');$('#deployment').scrollIntoView({block:'start'});}};
for(const id of ['survival-brief','hospice-brief'])$('#lab-scenario-body').append($('#'+id));
$('#lab-scenario-body').append($('.build-presets'));
view('adventure');

guildUI=mountGuild({configKey:storageKey,assertPreparation:()=>assertCurrentDraft(localStorage,config),editHero:(id,roomId,row,phase='prep')=>{selected=id;scope=roomId;planner();view("planning");setPrep("team");$("#editor").scrollIntoView({block:"start"});focusCommandRow(row,phase);tell("正在调整该队员战术。完成后点击公会出征重新核对实际配置。");},updateConfig:(c,undo,persisted)=>{replaceConfig(c,undo);scope='';if(persisted)savedState();else persist();planner();},getConfig:()=>config,loadConfig:(c,undo,persisted,options={})=>{replaceConfig(c,undo);scope="";if(options.overview)guideDismissed=false;if(persisted)savedState();else persist();planner();view("planning");setPrep(options.overview?"overview":"team");window.scrollTo({top:0});},showReport:loadReport,view,tell,download});
archiveCapture=mountArchiveCapture({getGuild:()=>readCycleGuild(localStorage),getReport:()=>report,getOrigin:()=>reportOrigin,onSave:(r,o,title)=>guildUI.saveReportArchive(r,o,title),onLibrary:()=>guildUI.open('history'),tell});
planner();guildUI.open();

function renderTrialBrief(){const isTrial=['seasoned','veteran'].includes(config.expedition);$('#trial-brief').hidden=!isTrial;if(!isTrial)return;$('#trial-brief').innerHTML=`<p class=eyebrow>阶段试炼 / ${config.expedition==='seasoned'?'建议熟练':'建议资深'}</p><h2>${EXPEDITIONS[config.expedition].name}</h2><p>${config.expedition==='seasoned'?'保护后排，分开处理高法抗治疗者与高远程抗性召唤者。':'双翼伏弩、中央群攻和末场支援链；调整站位并为后三名敌人保留资源。'}</p><p>以下方案用于对照思路，会载入整队战术、训练和补给；可撤销。公会出征仍使用实际持有的装备与训练。进阶技能可自行加入，建议阶段不是进入门槛。</p><div class=bar><button data-trial-plan="front">正面突破</button><button data-trial-plan="roles">统一职责集火</button><button data-trial-plan="adapted">分工与保护</button></div><p class=muted>先查看逐房敌情，再判断方案适不适合你的队伍；预设不保证通关。</p>`;}
$('#trial-brief').onclick=e=>{const b=e.target.closest('[data-trial-plan]');if(!b)return;const seed=config.seed;replaceConfig(trialConfig(config.expedition,b.dataset.trialPlan));config.seed=seed;scope='';persist();planner();tell('试炼对照方案已载入，种子保持不变；可在战术实验中保存A并比较。');};

for(const id of ['support-prev','support-next'])$('#'+id).onclick=e=>{if(e.currentTarget.dataset.at!==''){stop();move(Number(e.currentTarget.dataset.at));}};
$('#support-moment').onchange=e=>{if(e.target.value!==''){stop();move(Number(e.target.value));}};

$('#source-trace').onclick=e=>{if(e.target.closest('[data-support-evidence-return]')){supportEvidenceReturn=false;traceReturn=null;replayWorkspace.open('review',true);$('#support-evidence').scrollIntoView({block:'start'});return;}const origin=e.target.closest('[data-trace-origin]'),back=e.target.closest('[data-trace-return]');if(origin){if(traceReturn===null)traceReturn=index;stop();move(Number(origin.dataset.traceOrigin));$('#support-focus').scrollIntoView({block:'start'});}else if(back&&traceReturn!==null){const at=traceReturn;traceReturn=null;stop();move(at);$('#source-trace').scrollIntoView({block:'start'});}};

$('#highlights-only').onchange=()=>{stop();if(!report)return;if($('#highlights-only').checked)$('#diagnostic').checked=false;const list=allSteps();const selected=list.find(g=>index>=g.start&&index<=g.end)||list.find(g=>g.start>=index)||list.at(-1);renderJournal();if(selected)move(selected.start);};
$('#diagnostic').addEventListener('change',()=>{if($('#diagnostic').checked){$('#highlights-only').checked=false;renderJournal();frame();}});
$('#focus-action').onchange=()=>{if(report)frame();};

$('#theatre-mode').onchange=()=>{if($('#theatre-mode').checked)replayWorkspace.open('battle');document.body.classList.toggle('replay-focus',$('#theatre-mode').checked);if(report)requestAnimationFrame(()=>drawFx(stageFrame(selectedGroup())));$('.replay-controls').scrollIntoView({block:'start'});};
window.addEventListener('resize',()=>{if(report&&document.body.dataset.view==='replay')drawFx(stageFrame(selectedGroup()));});

$('#personal-playback').onchange=syncPersonalReplay;

function renderHarborPlan(){const enabled=config.expedition==='harbor';$('#harbor-plan').hidden=!enabled;$('#harbor-plan').innerHTML=harborPlanView(config);$('#harbor-brief').hidden=!enabled;$('#harbor-brief').innerHTML=enabled?'<p class="eyebrow">第二章 / 自动分支</p><h2>盐风港的无光灯塔</h2><p>每次四场战斗；通路与港口事件在抵达时按队伍状态执行。先在事件策略查看全部分支和条件，再核对实际公会装备。</p><button id="open-harbor-plan">查看港口分支计划 →</button>':'';}
$('#harbor-plan').onchange=e=>{if(e.target.dataset.harbor){config.harbor[e.target.dataset.harbor]=e.target.value;persist();planner();tell('港口策略已保存；实际结果将在远征抵达该节点时结算。');}};
$('#harbor-brief').onclick=e=>{if(e.target.id==='open-harbor-plan'){setPrep('events');$('#harbor-plan').scrollIntoView({block:'start'});}};
for(const el of [$('#harbor-journey'),$('#event-scene'),$('#harbor-assessment')])el.addEventListener('click',e=>{const b=e.target.closest('[data-harbor-source],[data-foundry-source],[data-courier-source]');if(b){stop();move(report.events.findIndex(x=>x.id===Number(b.dataset.harborSource||b.dataset.foundrySource||b.dataset.courierSource)));$('.stage').scrollIntoView({block:'start'});}});

$('#harbor-plan').onclick=e=>{const b=e.target.closest('[data-harbor-tactics]');if(!b)return;replaceConfig(applyHarborTactics(config,b.dataset.harborTactics));persist();planner();tell('已应用'+HARBOR_TACTICS[b.dataset.harborTactics].name+'；请核对公会实际指令，可在方案管理撤销。');};

function editFromReport(target){const [roomId,hero]=target.split(':');replaceConfig(report.config);savedA=clone(report.config);try{localStorage.setItem(storageKey+'-a',JSON.stringify(savedA));}catch{}scope=roomId;selected=hero;persist();planner();view('planning');setPrep('team');$('#editor').scrollIntoView({block:'start'});tell('已从战报出发配置开始修改，并将它冻结为 A。当前仅定位到该队员与房间，尚未自动修改任何战术。');}
for(const panel of [$('#harbor-assessment'),$('#foundry-outcome')])panel.addEventListener('click',e=>{const source=e.target.closest('[data-ledger-source]'),edit=e.target.closest('[data-review-edit]');if(source){stop();$('#highlights-only').checked=false;$('#diagnostic').checked=true;replayWorkspace.open('evidence');renderJournal();move(report.events.findIndex(x=>x.id===Number(source.dataset.ledgerSource)));$('#detail').scrollIntoView({block:'start'});}else if(edit)editFromReport(edit.dataset.reviewEdit);});

function openSupportEvidenceEvent(value){const at=report?.events.findIndex(e=>e.id===Number(value));if(at===undefined||at<0)return;stop();supportEvidenceReturn=true;traceReturn=null;$('#highlights-only').checked=false;$('#diagnostic').checked=true;replayWorkspace.open('evidence');renderJournal();move(at);$('#detail').scrollIntoView({block:'start'});}
$('#support-evidence').onclick=e=>{const source=e.target.closest('[data-support-evidence-event]'),edit=e.target.closest('[data-support-evidence-edit]');if(source)openSupportEvidenceEvent(source.dataset.supportEvidenceEvent);else if(edit)editFromReport(edit.dataset.supportEvidenceEdit);};
$('#support-evidence').onchange=e=>{if(e.target.id==='support-evidence-actor')$('#support-evidence').innerHTML=supportEvidenceView(supportEvidenceData,e.target.value);else if(e.target.matches('[data-support-evidence-record]')&&e.target.value)openSupportEvidenceEvent(e.target.value);};

$('#replay').addEventListener('click',e=>{const edit=e.target.closest('[data-healing-edit]');if(edit){editFromReport(edit.dataset.healingEdit);return;}const b=e.target.closest('[data-healing-origin]');if(!b)return;const at=Number(b.dataset.healingOrigin);if(!Number.isInteger(at)||!report?.events[at])return;traceReturn=index;stop();$('#highlights-only').checked=false;$('#diagnostic').checked=true;replayWorkspace.open('evidence');renderJournal();move(at);$('#support-focus').scrollIntoView({block:'start'});});

function renderFoundryBrief(){
 const enabled=config.expedition==='foundry';$('#foundry-brief').hidden=!enabled;if(!enabled)return;
 $('#foundry-brief').innerHTML='<p class="eyebrow">新支线 / 四场连续作战</p><h2>锈潮铸库：先拆配合，再取炉心。</h2><p>盐风港外的旧铸库重新轰鸣。链甲门场、第二场可选通路、熔盐坩埚与炉心封库连续作战；生命、法力、道具次数和30份补给跨房继承。整段自动执行，房间间不能临时改配。</p><p>建议熟悉职业分工后挑战，成长阶段不限制进入。先看四场敌情：首房聚集且弱法，第二场默认回廊两翼分散且有抗法药师，潮渠则有中央抗法咏唱者，第三房唤炉者反复补召，末房两类支援拥有不同抗性。所有压力来自可见技能与抗性，没有额外隐藏灼烧。</p><div class="bar"><button data-foundry-plan="split">载入分工集火</button><button data-foundry-plan="shelter">载入分阵护后</button><button data-foundry-plan="plain">载入直接推进</button></div><p>方案只提供战术起点，不赠送训练或装备。分阵方案把潮术师与药师移出中央，并把屏障转向后排；代价是失去集中辅助的部分覆盖。分工方案集中中央辅助，保留低耗后备，把材料留给指定支援。实际公会仍采用当前个人资产与已应用伙伴职责，请在出征前核对。</p><p>通关可带回风箱巡衣或炉心尺规；首通固定风箱巡衣。巡衣提高敏捷与远程抗性，降低智力及法术抗性；尺规提高感知/智力，牺牲体质。领取后可分配到个人装备栏。</p><details><summary>可选委托与定向遗物</summary><p>封存图纸：全员通关、累计不超过18回合并留下3符纸/3箭矢，首次正常结算获得尺规与20金币。整队归航：全员通关且总生命至少90%，首次获得巡衣与20金币。</p><p>无需另接任务，已完成不重复发奖；可到公会的远征委托查看记录。实验和重演只显示条件，不发奖励。</p></details>'+foundryPassageView(config);
}
$('#foundry-brief').onchange=e=>{if(e.target.id!=='foundry-approach')return;const next=clone(config);if(e.target.value==='bellows')delete next.foundryApproach;else {next.foundryApproach=e.target.value;next.foundryFlow='cooling-1';}replaceConfig(next);persist();planner();tell('通路策略已保存；抵达第二场时执行，实际公会仍采用当前资产与职责。');};
$('#foundry-brief').onclick=e=>{if(e.target.closest('[data-foundry-channel-plan]')){replaceConfig(channelTactics(config));scope='foundry_bellows';persist();planner();view('planning');setPrep('team');tell('第二场潮渠分工草案已载入；补给未改，伙伴托管请另行应用。');return;}const b=e.target.closest('[data-foundry-plan]');if(!b)return;const next=foundryConfig(b.dataset.foundryPlan);next.seed=config.seed;if(config.foundryApproach!==undefined)next.foundryApproach=config.foundryApproach;replaceConfig(preserveObjective(next));scope='';persist();planner();view('planning');setPrep('team');tell('铸库战术起点已载入；当前公会资产与已应用伙伴职责保留，请核对四场实际指令。');};

function renderWatchBrief(){
 const enabled=config.expedition==='foundrywatch';$('#watch-brief').hidden=!enabled;if(!enabled)return;
 $('#watch-brief').innerHTML='<p class="eyebrow">铸库后续 / 三场连续挑战</p><h2>封库守望：受压时仍要分清职责。</h2><p>建议完成铸库后再试，进入不限成长阶段。30份补给和生命、法力、道具次数跨场继承，整段自动执行。重卫与救护、双翼交叉压制与截疗、最后三类支援要求不同分工。先看下方完整敌情，再决定谁负责救护、召唤和屏障来源。</p><div class="bar"><button data-watch-plan="split">载入分工拆援</button><button data-watch-plan="shelter">载入分阵守望</button><button data-watch-plan="plain">载入直接推进</button></div><p>方案不赠送装备、培养或课程，也不替换公会已应用的伙伴职责。分阵减少中央聚集，却可能失去集中辅助与屏障覆盖；先打治疗者也会暂时留下其他支援。</p><p>每次通关带回一枚固定守望徽记，首通另有正常金币与个人经验。徽记提高意志、魅力和法术抗性，牺牲力量、灵巧及远程抗性；领取后分配，不是所有职业的升级。此路线与铸库两项一次性委托分开结算。</p>';
}
$('#watch-brief').onclick=e=>{const b=e.target.closest('[data-watch-plan]');if(!b)return;const next=watchConfig(b.dataset.watchPlan);next.seed=config.seed;replaceConfig(preserveObjective(next));scope='';persist();planner();view('planning');setPrep('team');tell('守望战术起点已载入；请核对公会实际资产与当前伙伴职责。');};

function renderCourierBrief(){const enabled=config.expedition==='courier';$('#courier-brief').hidden=!enabled;if(!enabled)return;$('#courier-brief').innerHTML='<p class="eyebrow">灯塔后续 / 三场连续远征</p><h2>沉船邮路：先让哪一种支援停下？</h2><p>回信已写好，截邮守军却仍封着旧航道。外港断桥、分舱或船底通路、回邮台连续作战，30份补给、生命、法力与道具次数跨房继承，整段自动执行。</p><p>鼓手的节拍增加行动；谱师的合奏本回合抢拍、下一回合才有余韵；印师的护印先给护甲、之后才提高防御技能。击倒来源只能阻止之后刷新，不能撤销已施放的组件或重排已确定的队列。先看三场敌情，再分配射手、法术与近战的职责。</p><div class="bar"><button data-courier-plan="rhythm">载入先断节拍</button><button data-courier-plan="ward">载入先拆护印</button><button data-courier-plan="plain">载入直接推进</button></div><p>前两种方案共同把潮术师移左、药师移右、学者移后，启蒙跟随潮术师；第二场屏障持续护中央，吟游者留中并用心智抵抗；射手每回合重箭压后排，药师提高到80%救护，需要为提前救护和重箭留足材料。中央为空时，敌方攻击仍会按规则回退到其他阵位。这会改变辅助覆盖与防御耗蓝。</p><p>两者只在末场潮术师优先目标上不同，另一个支援仍会施压。</p><p>中央承伤者可考虑盐晶护符与铁壁重甲（营地各60金币），以灵巧和先攻换取抗性、护甲。</p><p>起点将吟游者随身槽改为救急药匣，在70%生命时自救，占自己的普通行动。方案不会自动购装，也不赠送培养、课程或更改已应用伙伴职责。</p><p>通关固定获得回邮铜铃，正常领取后进仓库再分配。铜铃提高敏捷、意志与少量远程抗性，降低智力和法术抗性；是配装取舍，不是所有人的升级。</p>'+courierPassageView(config);}
$('#courier-brief').onchange=e=>{if(e.target.id!=='courier-pass')return;const next=clone(config);if(e.target.value==='sails')delete next.courierPass;else next.courierPass=e.target.value;replaceConfig(next);persist();planner();tell('邮路通路已保存；抵达第二场时按实际箭矢执行，缺料自动走分舱。');};
$('#courier-brief').onclick=e=>{if(e.target.closest('[data-courier-keel-plan]')){replaceConfig(keelTactics(config));scope='courier_sails';persist();planner();view('planning');setPrep('team');tell('第二场船底分工已载入；未改补给、资产或伙伴职责。');return;}const b=e.target.closest('[data-courier-plan]');if(!b)return;const next=courierConfig(b.dataset.courierPlan);next.seed=config.seed;if(config.courierPass!==undefined)next.courierPass=config.courierPass;replaceConfig(preserveObjective(next));scope='';persist();planner();view('planning');setPrep('team');tell('邮路战术起点已载入；请核对公会实际资产与当前伙伴职责。');};

function renderPalisadeBrief(){const enabled=config.expedition==='palisade';$('#palisade-brief').hidden=!enabled;if(!enabled)return;$('#palisade-brief').innerHTML='<p class=eyebrow>新地城 / 三场连续拆援</p><h2>折潮哨垒：盾墙护住了谁？</h2><p>护讯栈桥的前排盾卫护后排医师，交错弩台的后排卫长护前排弩兵，最后两卫与医师互相配合。援护不是固定免伤：每位来源每回合最多付2法力检定一次，成功才接招，随后正常防御。法术和心理不触发，每次攻击最多重定向一次，不在双卫之间连锁。先看三场完整敌情，再选择拆来源或绕过接招。</p><div class=bar><button data-palisade-plan=break>载入先拆来源</button><button data-palisade-plan=bypass>载入绕过救护</button><button data-palisade-plan=plain>载入直接推进</button></div><p>三起点30共享补给、同一装备与培养草案，带现有随身道具；不同方案改变目标、预备和免费专修位，不是单变量胜率推荐。不赠金币、经验、装备、课程或替换已应用伙伴职责。正常通关领取哨誓披甲：4护甲、体质+2/感知+1，代价为敏捷-2/智力-2、远程抗性+10%/法术抗性-10%；须从公会仓库明确分配。场景复用盐风港插画。</p>';};
$('#palisade-brief').onclick=e=>{const b=e.target.closest('[data-palisade-plan]');if(!b)return;const next=palisadeConfig(b.dataset.palisadePlan);next.seed=config.seed;replaceConfig(preserveObjective(next));scope='';persist();planner();view('planning');setPrep('team');tell('哨垒战术起点已载入；请核对实际装备、培养、目标和伙伴职责。');};

function renderInquestBrief(){const enabled=config.expedition==='inquest';$('#inquest-brief').hidden=!enabled;if(!enabled)return;$('#inquest-brief').innerHTML='<p class=eyebrow>新战斗系统 / 两场连续短线</p><h2>镜心问堂：护甲挡得住刀锋，心声需要另作准备。</h2><p>诘心回声为吟游者自由普通技能，需乐器，6法力、无共享材料。心理攻击沿用“法术 / 心理”栏的自然防御或心智抵抗及其培养；只按心理抗性减伤，物理护甲不参与，法术抗性不会转成心理抗性。挫志弦仍是法术，不随本次改型。</p><p>首场重甲近卫心理薄弱，后排问询者却抗心理；末场审守心理抗性更强、弱法，问询者压中央。先看完整敌情，再分配吟游者、射手和法师目标。定心吟提高意志、影响之后防御，屏障也帮助检定；先手击倒来源可减少后续攻击。净化不能撤销已造成的心理伤害。</p><div class=bar><button data-inquest-plan=pressure>载入诘心拆援</button><button data-inquest-plan=composure>定心守御（需已学定心吟）</button><button data-inquest-plan=plain>载入原有输出</button></div><p>两场24补给，生命、法力与道具次数连续继承。方案不赠送装备、培养或课程，不替换已应用伙伴职责。正常通关领取定心缎带：心理抗性+20%、意志+2，代价为敏捷-2、法术抗性-10%。场景复用镜廊插画。</p>';};
$('#inquest-brief').onclick=e=>{const b=e.target.closest('[data-inquest-plan]');if(!b)return;const next=inquestConfig(b.dataset.inquestPlan);next.seed=config.seed;replaceConfig(preserveObjective(next));scope='';persist();planner();view('planning');setPrep('team');tell('问堂战术起点已载入；请核对实际资产、目标和伙伴职责。');};

function renderTheaterBrief(){const enabled=config.expedition==='theater';$('#theater-brief').hidden=!enabled;if(!enabled)return;$('#theater-brief').innerHTML='<p class="eyebrow">新战斗系统 / 两场连续短线</p><h2>失声剧场：保住攻击节奏，还是先让对方失声？</h2><p>挫志弦是魅力/意志单体法术，使用既有心智抵抗和法术抗性；命中仍存活者后攻击技能等级-3，当前与下一回合有效。不叠加或刷新，来源倒下也保留到期。削弱不影响辅助、救护、防御技能或已发生的攻击。</p><p>清心符在预备阶段用4法力、1符纸，移除一个阵位最多3名存活者的负面效果，保留增益。无负面目标免费跳过并尝试下一条；需要在本回合的屏障与净化之间分配行动，不提供持续免疫。</p><div class="bar"><button data-theater-plan="plain">保留屏障、远程拆援</button><button data-theater-plan="cleanse">按房净化、后备屏障</button><button data-theater-plan="pressure">吟游者主动挫志</button></div><p>三起点都是24份补给、相同装备和培养。射手重箭后排、潮术师开场群攻前排；净化方案第一场护前、第二场护中，后备屏障轮转后重新检查净化。主动挫志把吟游者普通攻击改为每回合一次挫志、低耗后备，学者仍护前或护中；第二场潮术师改先拆左翼净谱师，让挫志不再被它净化。</p><p>载入不会赠送资产或改变已应用伙伴职责，请在出征前核对。击倒来源、接受暂时削弱继续输出、付符纸净化各有代价，不保证任何一种总更优。首通固定祷潮古琴，另一现有掉落为回声耳坠；正常领取后分配。</p>';}
$('#theater-brief').onclick=e=>{const b=e.target.closest('[data-theater-plan]');if(!b)return;const next=theaterConfig(b.dataset.theaterPlan);next.seed=config.seed;replaceConfig(preserveObjective(next));scope='';persist();planner();view('planning');setPrep('team');tell('剧场战术起点已载入，请核对实际资产、净化范围与伙伴职责。');};

function renderShoalsBrief(){const enabled=config.expedition==='shoals';$('#shoals-brief').hidden=!enabled;if(enabled)$('#shoals-brief').innerHTML=shoalsBriefView(config,guildUI?.snapshot());}
function changeShoalsChart(id){const next=clone(config);next.shoalsChart=id;validate(next);replaceConfig(next);persist();planner();tell('海图已更换，三场配置槽保留；请核对新敌群，再决定是否载入本图分工。');}
$('#shoals-brief').onchange=e=>{if(e.target.id==='shoals-chart')changeShoalsChart(Number(e.target.value));};
$('#shoals-brief').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.shoalsChart){changeShoalsChart(Number(b.dataset.shoalsChart));return;}if(b.dataset.shoalsRoom!==undefined){scope=SHOALS_SLOTS[Number(b.dataset.shoalsRoom)];planner();setPrep('team');$('#deployment').scrollIntoView({block:'start'});return;}if(b.dataset.shoalsPlan){const next=shoalsConfig(b.dataset.shoalsPlan,shoalsChartId(config));next.seed=config.seed;replaceConfig(preserveObjective(next));scope='';persist();planner();view('planning');setPrep('team');tell('本图战术起点已载入；海图和当前实际资产保留，请核对已应用伙伴职责。');}};

function renderScriptoriumBrief(){const enabled=config.expedition==='scriptorium';$('#scriptorium-brief').hidden=!enabled;if(!enabled)return;$('#scriptorium-brief').innerHTML='<p class=eyebrow>新地城 / 三场连续反制</p><h2>逆印书库：增益被拆之后，队伍怎样继续？</h2><p>抄录员、审校与裁师分别用破印压前排、中央和后排。命中存活目标后移除最早同技能/同来源一组增益，待生效组件也可能被移除；闪避不破除。破印先按当前增益筛选目标，不能把阵位写法当成必定攻击某个人。本次防御、此前检定与本回合固定行动仍保留；来源可在之后重新施放，须再支付材料。</p><p>先拆来源用重箭与一次长枪追击实际破印者，保留屏障与药膳；少用增益取消药膳/吟游辅助、改微光和穿石箭，减少单次普通攻击耗材；战斗可能拉长，总消耗与受击风险可能更高；重施护印在同房交替检查护印与屏障，学者也以破印反制敌方守势。三方案改变多项战术，不是胜率推荐，均30共享补给、相同原始装备与培养，随身道具占普通行动；不赠送资产或替换已应用伙伴职责。</p><div class=bar><button data-scriptorium-plan=source>载入先拆来源</button><button data-scriptorium-plan=lean>载入少用增益</button><button data-scriptorium-plan=renew>载入重施护印</button></div><p>通关固定辨印晶镜：智力+2/感知+1，代价为体质-2/意志-1；法术抗性+10%、心理抗性-10%。它增加相应法术检定，却减少生命并弱心理，末场问卷者需要另作防护。奖励须正常领取并明确分配，场景复用镜廊插画。</p>';}
$('#scriptorium-brief').onclick=e=>{const b=e.target.closest('[data-scriptorium-plan]');if(!b)return;const next=scriptoriumConfig(b.dataset.scriptoriumPlan);next.seed=config.seed;replaceConfig(preserveObjective(next));scope='';persist();planner();view('planning');setPrep('team');tell('书库战术起点已载入；请核对实际资产、逐房目标与伙伴职责。');};

function renderGreenhouseBrief(){const enabled=config.expedition==='greenhouse';$('#greenhouse-brief').hidden=!enabled;if(!enabled)return;$('#greenhouse-brief').innerHTML='<p class=eyebrow>新地城 / 三场持续侵蚀</p><h2>蚀潮温室：药草和符纸该留给谁？</h2><p>苗圃调剂师、栽植者与母株依次压前排、中央和后排。药剂初击需要命中，潮蚀之后两个回合开始按基值6/当时法术抗性跳伤，不再攻防检定；通常首跳先于净化，清心只能移除后续跳。来源倒下不解除已附着状态。中场敌方学徒也会净化前排，不能把自己的施药次数当作稳定伤害。</p><p>先拆来源保留按房屏障，试图减少初击和之后施药；按房净化以清心替代屏障，支付预备/符纸移除已附负面，没有负面时免费跳过；药蚀反制保留屏障并让药师每房一次施药，与80%自动救护共用药草，免费专修也从救护转给药剂。三种起点多项配置有别，不是最优推荐，均30共享补给、同初始装备/培养与现有随身道具，不赠资产或替换已应用伙伴职责。</p><div class=bar><button data-greenhouse-plan=source>载入先拆来源</button><button data-greenhouse-plan=cleanse>载入按房净化</button><button data-greenhouse-plan=corrode>载入药蚀反制</button></div><p>固定滤露面纱提供法术抗性+20%、意志+2，代价为智力-2/敏捷-1和法力上限-2；能减少潮蚀实伤，不能免疫或让心智抵抗代防跳伤。奖励须正常领取并明确分配，场景复用疗所插画。</p>';}
$('#greenhouse-brief').onclick=e=>{const b=e.target.closest('[data-greenhouse-plan]');if(!b)return;const next=greenhouseConfig(b.dataset.greenhousePlan);next.seed=config.seed;replaceConfig(preserveObjective(next));scope='';persist();planner();view('planning');setPrep('team');tell('温室起点已载入；请核对实际资产、逐房目标与净化/救护分工。');};

function campMapView(){try{return campCycleView(campObjective(readCycleGuild(localStorage)));}catch{return '<section class="panel"><p>公会暂不可读，原存档未覆盖；请回营导出或恢复有效备份。</p><button data-cycle-action=hero>回营检查</button></section>';}}
function refreshReportHandoff(){const box=$('#report-handoff');if(!box)return;box.hidden=!report;if(!report)return;try{const state=reportHandoff(readCycleGuild(localStorage),reportOrigin,report);box.dataset.status=state.status;box.innerHTML=reportHandoffView(state,objectiveResultView(report));archiveCapture?.render();}catch{archiveCapture?.hide();box.dataset.status='unavailable';box.innerHTML='<h2>公会暂不可读取</h2><p>原存档未覆盖，不能从这里领取；请回营检查或恢复备份。</p><button data-report-cycle=camp>回营检查</button>';}}
$('#report-handoff').onclick=e=>{const proof=e.target.closest('[data-objective-event]');if(proof){stop();$('#personal-playback').checked=false;$('#highlights-only').checked=false;$('#diagnostic').checked=true;replayWorkspace.open('evidence');renderJournal();move(Number(proof.dataset.objectiveEvent));$('#detail').scrollIntoView({block:'start'});return;}if(e.target.closest('[data-objective-edit]')){try{replaceConfig(report.config);savedA=clone(report.config);try{localStorage.setItem(storageKey+'-a',JSON.stringify(savedA));}catch{}scope='';persist();planner();view('planning');setPrep('overview');tell('本次目标与方案已载入，并冻结为A供对照。请按当前公会资产与伙伴职责调整；待领远征不变，正式重试仍须先正常领取。');}catch(error){tell('未能载入目标方案：'+error.message);}return;}const b=e.target.closest('[data-report-cycle]');if(!b)return;try{if(b.dataset.reportCycle==='claim')guildUI.settleReport(reportOrigin,report);else guildUI.cycle(b.dataset.reportCycle);}catch(error){tell(error.message);}refreshReportHandoff();};
window.addEventListener('storage',e=>{if(!e.key||e.key===storageKey)refreshPreparationStatus();if(!e.key||e.key==='abbey-guild-v6')refreshReportHandoff();});
window.addEventListener('focus',()=>{refreshPreparationStatus();refreshReportHandoff();});

function renderClocktower(){const box=$('#clocktower-brief');box.hidden=config.expedition!=='clocktower';if(box.hidden)return;box.innerHTML='<p class=eyebrow>三场连续 / 时机与资源</p><h2>同一座钟楼，不同的行动时机。</h2><p>门厅第三回合蓄势，齿廊第一回合急拍，观台早期屏障与之后冲击。完整敌人指令与窗口在敌情中公开；每房重新计时，已生效效果不因窗口结束自动撤销。时序只是构筑选择，不保证及时出手或胜利。</p><div class=bar>'+Object.entries({rush:'先拆来源',timed:'分房防护与延迟爆发',steady:'低耗持续'}).map(([id,name])=>`<button data-clocktower-plan="${id}">${name}</button>`).join('')+'</div><p>起点替换战术草稿，保留本次种子和目标；公会仍按当前资产与已应用伙伴职责核对。潮刻怀表需正式通关领取、明确分配。</p>';}
$('#clocktower-brief').onclick=e=>{const b=e.target.closest('[data-clocktower-plan]');if(!b)return;const c=clocktowerConfig(b.dataset.clocktowerPlan);c.seed=config.seed;replaceConfig(preserveObjective(c));scope='';persist();planner();view('planning');setPrep('team');tell('钟楼战术起点已载入；请逐房核对实际指令与伙伴职责。');};

function renderConfluenceBrief(){const box=$('#confluence-brief');box.hidden=config.expedition!=='confluence';if(box.hidden)return;box.innerHTML='<p class=eyebrow>新地城 / 三场连续分工</p><h2>合流救护站：群攻受伤之后，谁让整排重新站稳？</h2><p>药棚医师救前排，桥侧医师转救后排且受援护，分诊台同时有只自救的抄录员与合剂医师。所有人沿现有规则行动：同位至少两名达阈值伤员时群救，不足条件回单救；敌方药草独立，未借用玩家补给。</p><p>分摊伤害可能让敌方一次恢复多人；先拆来源可减少后续救护，截疗需要实际命中且及时出手。末房治疗者有两名候选，职责目标不保证总打中同一人。下方完整敌情公开范围、优先策略、技能等级与单次费用。</p><div class=bar>'+Object.entries({source:'先拆合剂来源',suppress:'截疗与阵位群攻',spread:'散阵与低耗追击'}).map(([id,name])=>`<button data-confluence-plan="${id}">${name}</button>`).join('')+'</div><p>三个可改起点使用相同30补给及既有资产预算，改变多项战术，不是单变量强弱推荐。不会赠装备/培养/课程或改公会已应用职责；托管伙伴请在实际出征卡核对。正常通关领取固定分诊铜签：智力/感知/远程抗性收益，体质、意志与法术抗性代价，领取后再明确分配。</p>';}
$('#confluence-brief').onclick=e=>{const b=e.target.closest('[data-confluence-plan]');if(!b)return;const c=confluenceConfig(b.dataset.confluencePlan);c.seed=config.seed;if(config.objective)c.objective=config.objective;if(config.withdrawAt!==undefined)c.withdrawAt=config.withdrawAt;replaceConfig(c);scope='';persist();planner();tell('已载入合流救护站起点；种子/目标保留，公会资产与已应用职责不变，可撤销。');};

$('#replay').addEventListener('click',e=>{const b=e.target.closest('[data-offbeat-origin]');if(!b)return;stop();if(traceReturn===null)traceReturn=index;$('#diagnostic').checked=true;renderJournal();move(Number(b.dataset.offbeatOrigin));replayWorkspace.open('evidence');$('#detail').scrollIntoView({block:'start'});});

function renderCounterpoint(){const box=$('#counterpoint-brief');box.hidden=config.expedition!=='counterpoint';if(box.hidden)return;box.innerHTML='<p class=eyebrow>两场单人短线 / 24补给</p><h2>错拍回廊：保留急拍，还是先清掉迟声？</h2><p>敌方使用同一迟拍弦，命中后只减下一回合至多一次额外行动；基础行动和当前队列继续。门廊来源在后排，走台来源在左翼且受物理援护、第2回合起出手。净化占预备、法力与符纸；少用节拍会失去额外行动收益，先拆来源也不会撤销已经附着的迟拍。</p><div class=bar>'+Object.entries({tempo:'急拍推进，承受迟拍',cleanse:'保留急拍，净化优先',source:'少用急拍，逐房拆来源'}).map(([id,name])=>`<button data-counterpoint-plan="${id}">${name}</button>`).join('')+'</div><p>三个可改起点只改指令，不赠资产或培养，不是单变量最优推荐；24携带预算仍按每次远征使用。通关领取金币与经验，没有装备掉落或额外目标奖励。全部遭遇、费用和奖励为项目原创暂定内容。</p>';}
$('#counterpoint-brief').onclick=e=>{const b=e.target.closest('[data-counterpoint-plan]');if(!b)return;const c=counterpointConfig(b.dataset.counterpointPlan);c.seed=config.seed;if(config.objective)c.objective=config.objective;if(config.withdrawAt!==undefined)c.withdrawAt=config.withdrawAt;replaceConfig(c);scope='';persist();planner();tell('已载入错拍回廊起点；保留种子/目标，真实资产与已应用职责不变，可撤销。');};

$('#withdrawal-plan').onchange=e=>{if(e.target.id!=='withdraw-at')return;try{replaceConfig(withWithdrawal(config,Number(e.target.value)));persist();planner();tell('整队撤退计划已保存；实际出征将按此人数检查，未清场不算通关，可在方案管理撤销。');}catch(error){tell(error.message);planner();}};

function renderBreakwater(){const box=$('#breakwater-brief');box.hidden=config.expedition!=='breakwater';if(box.hidden)return;box.innerHTML='<p class=eyebrow>同房分波增援 / 两房30补给</p><h2>潮堤接应：清完眼前这一波，后面的配合还够用吗？</h2><p>'+WAVE_RULE+'</p><p>雾堤首波没有医师，追浪接应队才出现后排医师；堤台从左翼术士与援护，转为后排双弩齐射。全部模板在下方按波公开，未到场者不能提前成为实际目标。每房所有波都完成才算通过，单波不领奖，无装备掉落。</p><div class=bar>'+Object.entries({advance:'本房一次强攻与急拍',hunt:'按实际医师到场追击',steady:'低耗持续，少用急拍'}).map(([id,name])=>`<button data-breakwater-plan="${id}">${name}</button>`).join('')+'</div><p>三个可改起点改变多项指令，不是单变量最优结论，不赠资产/培养；遭遇、波次时机与奖励为项目原创暂定设计。</p>';}
$('#breakwater-brief').onclick=e=>{const b=e.target.closest('[data-breakwater-plan]');if(!b)return;const c=breakwaterConfig(b.dataset.breakwaterPlan);c.seed=config.seed;if(config.objective)c.objective=config.objective;if(config.withdrawAt!==undefined)c.withdrawAt=config.withdrawAt;replaceConfig(c);scope='';persist();planner();tell('已载入潮堤接应起点，保留种子/目标/撤退计划，真实资产与伙伴职责不变，可撤销。');};
$('#replay').addEventListener('click',e=>{const origin=e.target.closest('[data-wave-clear]'),back=e.target.closest('[data-wave-return]');if(origin){const at=report?.events.findIndex(x=>x.id===Number(origin.dataset.waveClear)&&x.type==='wave-clear'&&x.roomIndex===room);if(at===undefined||at<0)return;stop();waveReturn=index;renderJournal();move(at);replayWorkspace.open('evidence');$('#detail').scrollIntoView({block:'start'});}else if(back&&waveReturn!==null){const at=waveReturn;waveReturn=null;stop();move(at);$('#detail').scrollIntoView({block:'start'});}});

function renderOssuary(){const box=$('#ossuary-brief');box.hidden=config.expedition!=='ossuary';if(box.hidden)return;box.innerHTML='<p class=eyebrow>两场单人短线 / 24补给</p><h2>潮影墓廊：同一队伍，不同攻击的去处。</h2><p>先读下方每个敌人的公开免疫。前排雾壳由法术/心理处理，刻纹由物理处理；第二房再按药师、影子与弩卫分工。免疫不等于100%抗性，破甲和驱散不能解除。</p><p>选择起点后仍须核对自己的装备、训练、伙伴职责和实际目标；不会赠送资产或保证通过。全物理无法清首房，可先实验观察免费后备或行动空过。</p><div class=bar><button data-ossuary-plan=divide>物理与法术分工</button><button data-ossuary-plan=voices>吟游者追击侍药</button></div><small>'+IMMUNITY_RULE+'</small>';}
$('#ossuary-brief').onclick=e=>{const b=e.target.closest('[data-ossuary-plan]');if(!b)return;const c=ossuaryConfig(b.dataset.ossuaryPlan);c.seed=config.seed;if(config.objective)c.objective=config.objective;if(config.withdrawAt!==undefined)c.withdrawAt=config.withdrawAt;replaceConfig(c);scope='';persist();planner();tell('墓廊起点已载入；种子/目标/撤退条件保留，真实资产与已应用职责仍按公会出征核对。');};

function renderLockworks(){const box=$('#lockworks-brief');box.hidden=config.expedition!=='lockworks';if(box.hidden)return;box.innerHTML='<p class=eyebrow>两房30补给 / 机关供能</p><h2>潮锁护库：先切断哪一份防护？</h2><p>单锁为护库卫加12护甲；双锁各加8，只拆一台不会解除另一台。心理攻击可绕既有护甲，法术与附加法术段仍按原护甲；所有机关最后都须清除。</p><div class=bar><button data-lockworks-plan=disarm>射手先拆源</button><button data-lockworks-plan=bypass>先追医，吟游者绕甲</button></div><p>两种起点改变B首条目标和E生命输出方式，有行动/法力/箭矢代价，不保证节省药草。全部关联在下方公开，不是破印可移除的技能增益。</p><small>'+WARD_RULE+'</small>';}
$('#lockworks-brief').onclick=e=>{const b=e.target.closest('[data-lockworks-plan]');if(!b)return;const c=lockworksConfig(b.dataset.lockworksPlan);c.seed=config.seed;if(config.objective)c.objective=config.objective;if(config.withdrawAt!==undefined)c.withdrawAt=config.withdrawAt;replaceConfig(c);scope='';persist();planner();tell('护库起点已载入；请核对实际资产与伙伴职责，可在方案管理撤销。');};
$('#replay').addEventListener('click',e=>{const b=e.target.closest('[data-ward-cause]');if(b)openSupportEvidenceEvent(b.dataset.wardCause);});
function renderTrapworks(){const box=$('#trapworks-brief');box.hidden=config.expedition!=='trapworks';if(box.hidden)return;box.innerHTML='<p class=eyebrow>两场30补给 / 地城机关</p><h2>潮闸机廊：谁来拆，谁来保护？</h2><p>机弩压后排，喷口压中央；射手的机巧拆解占普通行动和3法力，无材料。其他队员先清生物/保护受压阵位；普通攻击不能破坏机关，普通治疗和增益不能修理它。全部敌人含机关清除才算过房。</p><div class=bar><button data-trapworks-plan=disarm>先拆机关，再追医</button><button data-trapworks-plan=rush>先打一发后排，再拆机关</button></div><p>两个可改起点仅改变射手首条重箭时机；先射击多花箭矢并可能让机关多行动，不保证省料。没有机巧拆解的合法配置可先实验，仍可能24回合无法清场。正常领取金币经验，没有装备掉落或额外拆解奖励。</p><small>'+MECHANISM_RULE+'</small>';}
$('#trapworks-brief').onclick=e=>{const b=e.target.closest('[data-trapworks-plan]');if(!b)return;const c=trapworksConfig(b.dataset.trapworksPlan);c.seed=config.seed;if(config.objective)c.objective=config.objective;if(config.withdrawAt!==undefined)c.withdrawAt=config.withdrawAt;replaceConfig(c);scope='';persist();planner();tell('机廊起点已载入；保留种子/目标/撤退条件，实际资产与已应用职责不变，可撤销。');};

function renderBeaconbridge(){const box=$('#beaconbridge-brief');box.hidden=config.expedition!=='beaconbridge';if(box.hidden)return;box.innerHTML='<p class=eyebrow>三场30补给 / 套装探索</p><h2>灯桥巡行：凑齐之后，仍要选择。</h2><p>两件灯桥守望提供法术保护，三件另有智力/远程保护和心理弱点。巡弩、援护救护与末房心理压中央要求不同分工；装备在出征中不能换，分房站位/指令可预设。普通首通固定号琴，重复三部件池不保证缺件；领取入仓后再分配和穿戴。</p><div class=bar>'+Object.entries({roles:'分工清援',steady:'低耗追击',swift:'后排急拍'}).map(([id,name])=>`<button data-beaconbridge-plan="${id}">${name}</button>`).join('')+'</div><p>战术起点只替换草稿，保留本次种子和目标；不会授予套装或永久培养。</p>'; }
$('#beaconbridge-brief').onclick=e=>{const b=e.target.closest('[data-beaconbridge-plan]');if(!b)return;const c=beaconbridgeConfig(b.dataset.beaconbridgePlan);c.seed=config.seed;if(config.objective!==undefined)c.objective=config.objective;replaceConfig(c);scope='';persist();planner();view('planning');setPrep('team');tell('灯桥战术起点已载入，实际套装/装备/培养仍以公会出征核对为准。');};
